import { Book } from "@/lib/types";

export const nehemiah: Book = {
  id: "nehemiah",
  name: "Nehemia",
  shortName: "Neh",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Geschichte* Nehemias, des Sohnes Hachaljas. Und es geschah im Monat Kislew* des zwanzigsten Jahres*, als ich in der Burg Susa* war,", heading: "Trauer Nehemias über den Zustand Judas und Jerusalems", footnotes: ["w. Worte", "d. i. der dritte Monat des bürgerlichen Jahres, das im Herbst (September/Oktober) begann\n℘ Sach 7,1", "d. h. der Regierung des Artaxerxes I. (465—424 v. Chr.)\n℘ Kap. 2,1; Esr 7,7", "℘ Est 1,2; Dan 8,2"] },
      { number: 2, text: "da kam Hanani, einer von meinen Brüdern*, er und einige Männer aus Juda. Und ich fragte sie nach den Juden, den Entkommenen, die von den Gefangenen übrig geblieben waren*, und nach Jerusalem*.", footnotes: ["℘ Kap. 7,2", "d. h. entweder die, die nicht in die Gefangenschaft geraten, oder die, die bereits zurückgekehrt waren\n℘ 2Kö 24,14", "℘ Ps 137,5"] },
      { number: 3, text: "Und sie sagten zu mir: Die Übriggebliebenen, die von den Gefangenen dort in der Provinz* übrig geblieben sind*, <leben> in großem Unglück und in Schmach*. Und die Mauer von Jerusalem ist niedergerissen*, und seine Tore sind mit Feuer verbrannt*.", footnotes: ["d. i. der persische Verwaltungsbezirk Juda mit der Hauptstadt Jerusalem", "d. h. entweder die, die nicht in die Gefangenschaft geraten, oder die, die bereits zurückgekehrt waren", "℘ Ps 79,4", "℘ 2Kö 25,10", "℘ Kap. 2,3.13.17; 3Mo 26,31.33; 2Chr 36,19; Kla 2,9"] },
      { number: 4, text: "Und es geschah, als ich diese Worte hörte, setzte ich mich hin, weinte* und trauerte tagelang*. Und ich fastete und betete* vor dem Gott des Himmels*.", footnotes: ["℘ 2Kö 22,19", "℘ Ps 102,15; Dan 10,2", "o. flehte\n℘ 2Chr 6,13; Esr 9,5; Dan 9,3", "℘ Kap. 2,4.20; Esr 1,2"] },
      { number: 5, text: "Und ich sprach: Ach, HERR, Gott des Himmels*, du großer und furchtbarer Gott*, der den Bund und die Gnade denen bewahrt, die ihn lieben und seine Gebote bewahren*!", footnotes: ["℘ Kap. 2,4.20; Esr 1,2", "℘ Kap. 4,8; 9,32; 5Mo 7,9.12.21; Ps 76,8; 89,8", "℘ Dan 9,4"] },
      { number: 6, text: "Lass doch dein Ohr aufmerksam und deine Augen offen sein, dass du auf das Gebet* deines Knechtes hörst, das ich heute, Tag und Nacht, für die Söhne Israel, deine Knechte, vor dir bete* und mit dem ich die Sünden der Söhne Israel bekenne, die wir gegen dich begangen haben! Auch ich und meines Vaters Haus, wir haben gesündigt*.", footnotes: ["o. das Flehen", "o. flehe\n℘ 1Kö 8,28.29", "℘ Esr 9,6; Dan 9,5.8"] },
      { number: 7, text: "Sehr böse haben wir gegen dich gehandelt und haben nicht die Gebote und die Ordnungen und die Rechtsbestimmungen bewahrt, die du deinem Knecht Mose geboten hast*.", footnotes: ["℘ Ps 89,31.32"] },
      { number: 8, text: "Denke doch an das Wort, das du deinem Knecht Mose geboten hast, indem du sprachst: Werdet ihr treulos handeln, dann werde ich euch unter die Völker zerstreuen*!", footnotes: ["℘ 5Mo 4,27; Hes 5,10; 6,8"] },
      { number: 9, text: "Kehrt ihr aber zu mir um und bewahrt meine Gebote und tut sie* — wenn <auch> eure Vertriebenen am Ende des Himmels sein sollten, <selbst> von dort werde ich sie sammeln und sie an den Ort bringen, den ich erwählt habe, um meinen Namen dort wohnen zu lassen*!", footnotes: ["℘ 3Mo 26,3; 5Mo 4,30", "℘ 5Mo 12,5.11; 30,1-4; Sach 8,7"] },
      { number: 10, text: "Sie sind ja deine Knechte und dein Volk*, das du erlöst hast durch deine große Kraft und deine starke Hand*.", footnotes: ["℘ 2Mo 6,7", "℘ 2Mo 13,3.14.16; 5Mo 9,29; Ps 89,14"] },
      { number: 11, text: "Ach, Herr, lass doch dein Ohr aufmerksam sein auf das Gebet* deines Knechtes* und auf das Gebet* deiner Knechte, die gewillt sind*, deinen Namen zu fürchten*! Lass es doch deinem Knecht heute gelingen und gewähre ihm Barmherzigkeit vor diesem Mann*! — Ich war nämlich Mundschenk des Königs*.", footnotes: ["o. das Flehen", "℘ Ps 86,6", "o. das Flehen", "o. die Freude daran haben", "℘ Mal 3,16", "℘ 1Mo 43,14", "℘ Kap. 2,1"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und es geschah im Monat Nisan*, im zwanzigsten Jahr des Königs Artahsasta*, als Wein vor ihm <stand>*, da nahm ich den Wein und gab ihn dem König*. Ich war aber nie traurig vor ihm gewesen*.", heading: "Nehemias Vollmacht für den Bau der Mauer Jerusalems — Besichtigung der Mauer und Entschluss zum Bauen", footnotes: ["d. i. der siebte Monat des bürgerlichen Jahres (März/April)\n℘ Est 3,7", "d. h. der Regierung des Artaxerxes I. (465—424 v. Chr.)\n℘ Kap. 1,1; Esr 4,7", "mehrere LXX-Handschr.: als Wein vor mir stand; d. h. als ich für den Wein zu sorgen hatte", "℘ Kap. 1,11", "mehrere LXX-Handschr.: Ich war aber traurig vor ihm"] },
      { number: 2, text: "Und der König sagte zu mir: Warum <sieht> dein Gesicht so traurig <aus>? Du bist <doch> nicht etwa krank? <Nein,> das ist es nicht, sondern ein trauriges Herz*! Da bekam ich einen furchtbaren Schrecken.", footnotes: ["℘ 1Mo 40,7; Spr 13,12; 15,13"] },
      { number: 3, text: "Und ich sagte zum König: Der König lebe ewig*! Warum sollte mein Gesicht nicht traurig <aussehen>*, wo doch die Stadt, die Begräbnisstätte meiner Väter, verödet daliegt und ihre Tore vom Feuer verzehrt sind?*", footnotes: ["℘ 1Kö 1,31", "℘ Ps 38,7", "℘ Kap. 1,3; Est 8,6"] },
      { number: 4, text: "Und der König sagte zu mir: Um was also bittest du?* Da betete* ich zu dem Gott des Himmels*", footnotes: ["℘ Est 5,3.6", "o. flehte", "℘ Kap. 1,4.5; Ps 136,26"] },
      { number: 5, text: "und sagte <dann> zum König: Wenn es dem König gefällt, und wenn dein Knecht wohlgefällig vor dir ist, so wollest du mich nach Juda senden zu der Stadt der Gräber meiner Väter, damit ich sie <wieder> aufbaue!" },
      { number: 6, text: "Da sagte der König zu mir — und die Königin saß neben ihm —: Wie lange wird deine Reise dauern, und wann wirst du zurückkehren? Und es war wohlgefällig vor dem König, so dass er mich sandte, und ich gab ihm eine Zeit* an*.", footnotes: ["w. Festsetzung", "℘ Kap. 13,6; Dan 9,25"] },
      { number: 7, text: "Und ich sagte zum König: Wenn es dem König gefällt, dann gebe man mir Briefe an die Statthalter jenseits des Stromes* <mit>, damit sie mich durchziehen lassen, bis ich nach Juda komme,", footnotes: ["d. i. westlich des Euphrat"] },
      { number: 8, text: "dazu einen Brief an Asaf, den Hüter über den Forst des Königs, damit er mir Holz gibt, dass ich die Tore der Burg, die zum <Tempel>haus gehört, aus Balken bauen kann und für die Mauer der Stadt und für das Haus, in das ich einziehen will*. Und der König gewährte es mir, weil die gute Hand meines Gottes über mir war*.", footnotes: ["℘ Esr 6,8", "w. entsprechend der guten Hand meines Gottes über mir\n℘ V. 18; Esr 7,6.9; Spr 21,1"] },
      { number: 9, text: "Und ich kam zu den Statthaltern jenseits des Stromes* und gab ihnen die Briefe des Königs. — Der König aber hatte Heeroberste und Reiter mit mir gesandt*. —", footnotes: ["d. i. westlich des Euphrat", "℘ Esr 8,22"] },
      { number: 10, text: "Und als Sanballat, der Horoniter, und Tobija*, der ammonitische Knecht, <davon> hörten, bereitete es ihnen großen Verdruss*, dass ein Mensch gekommen war, um das Wohl der Söhne Israel zu suchen*.", footnotes: ["℘ Kap. 3,35; 6,1; 13,4", "℘ Kap. 3,33; 4,1; Ps 112,10", "℘ Est 10,3"] },
      { number: 11, text: "Und ich kam nach Jerusalem und war drei Tage dort*.", footnotes: ["℘ Esr 8,32"] },
      { number: 12, text: "Und ich machte mich bei Nacht auf, ich und einige wenige Männer mit mir. Ich hatte aber keinem Menschen mitgeteilt, was mein Gott mir ins Herz gegeben hatte, für Jerusalem zu tun*. Und es war kein Tier bei mir, außer dem <Reit>tier, auf dem ich ritt.", footnotes: ["℘ Spr 12,23"] },
      { number: 13, text: "So zog ich nachts durch das Taltor* hinaus, in Richtung auf die Drachenquelle und das Aschentor*. Und ich untersuchte die Mauern von Jerusalem, die niedergerissen, und ihre Tore, die vom Feuer verzehrt waren*.", footnotes: ["℘ Kap. 3,13; 2Chr 26,9", "o. Misttor\n℘ Kap. 3,13.14; 12,31", "℘ Kap. 1,3"] },
      { number: 14, text: "Und ich zog hinüber zum Quellentor* und zum Königsteich*. Als aber für das <Reit>tier unter mir kein Raum <mehr> da war durchzukommen,", footnotes: ["℘ Kap. 3,15; 12,37", "℘ Kap. 3,16; 2Kö 20,20"] },
      { number: 15, text: "stieg ich bei Nacht das Bachtal hinauf und untersuchte die Mauer. Und ich kam wieder herein durch das Taltor*. So kehrte ich zurück.", footnotes: ["℘ Kap. 3,13; 2Chr 26,9"] },
      { number: 16, text: "Die Vorsteher aber hatten nicht erkannt, wohin ich gegangen war und was ich getan hatte. Denn ich hatte den Juden und den Priestern und den Edlen* und den Vorstehern und dem Rest, der an dem Werk mitarbeiten sollte, bis dahin nichts mitgeteilt*.", footnotes: ["w. den Freigeborenen", "℘ Spr 12,23"] },
      { number: 17, text: "Nun sagte ich zu ihnen: Ihr seht das Unglück, in dem wir sind, dass Jerusalem verödet daliegt und seine Tore mit Feuer verbrannt sind*. Kommt und lasst uns die Mauer Jerusalems <wieder> aufbauen*, damit wir nicht länger geschmäht werden können*!", footnotes: ["℘ Kap. 1,3", "℘ Esr 9,9; Mi 7,11", "w. damit wir nicht länger <für unsere Nachbarn> eine Schmach sind\n℘ Ps 44,14.15; 102,15; Hes 5,14"] },
      { number: 18, text: "Und ich berichtete von der Hand meines Gottes, die gütig über mir <gewaltet hatte>*, und auch von den Worten des Königs, die er zu mir geredet hatte. Da sagten sie: Wir wollen uns aufmachen und bauen! Und sie stärkten ihre Hände zum Guten.", footnotes: ["℘ V. 8"] },
      { number: 19, text: "Als aber Sanballat, der Horoniter, und Tobija, der ammonitische Knecht, und Geschem, der Araber, <davon> hörten, spotteten sie über uns und verachteten uns* und sagten: Was ist das für eine Sache, die ihr da tun wollt? Wollt ihr euch gegen den König empören*?", footnotes: ["℘ Kap. 3,33; Ps 80,7", "℘ Kap. 6,6"] },
      { number: 20, text: "Da gab ich ihnen zur Antwort und sagte zu ihnen: Der Gott des Himmels*, er lässt es uns gelingen. Und wir, seine Knechte, wollen uns aufmachen und bauen*. Ihr aber habt weder Anteil noch Anrecht, noch Gedenken in Jerusalem*.", footnotes: ["℘ Kap. 1,4.5", "℘ Ps 102,17", "℘ Esr 4,3; 2Kor 6,15"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und der Hohepriester Eljaschib* machte sich mit seinen Brüdern, den Priestern, auf, und sie bauten das Schaftor. Sie heiligten es *und setzten seine Torflügel ein. Und sie heiligten es* bis an den Turm Mea, bis an den Turm Hananel*.", heading: "Bau der Mauer — Namen der Bauleute", footnotes: ["℘ V. 20; Kap. 12,10.22; 13,4", "Andere üs. mit Textänderung: sie bauten es mit Balken", "Andere üs. mit Textänderung: sie bauten es mit Balken", "℘ Kap. 12,39; Jer 31,38; Sach 14,10"] },
      { number: 2, text: "Und ihm zur Seite bauten die Männer von Jericho. Und daneben* baute Sakkur, der Sohn Imris.", footnotes: ["w. an seiner Seite"] },
      { number: 3, text: "Und das Fischtor* bauten die Söhne Senaas*. Sie bauten es aus Balken und setzten seine Torflügel ein, seine Riegel und seine Sperrbalken.", footnotes: ["℘ Kap. 12,39; 2Chr 33,14; Zef 1,10", "℘ Kap. 7,38; Esr 2,35"] },
      { number: 4, text: "Und ihnen zur Seite besserte Meremot aus, der Sohn Urias, des Sohnes des Hakkoz*. Und daneben* besserte Meschullam* aus, der Sohn Berechjas, des Sohnes Meschesabels. Und daneben* besserte Zadok aus, der Sohn Baanas.", footnotes: ["℘ Kap. 7,63; Esr 2,61; 8,33", "w. an ihrer Seite", "℘ Kap. 6,18", "w. an ihrer Seite"] },
      { number: 5, text: "Und daneben* besserten die Tekoïter* aus. Aber die Vornehmen unter ihnen beugten* ihren Nacken nicht zum Dienst für ihren Herrn*.", footnotes: ["w. an seiner Seite", "℘ 2Chr 11,6; Jer 6,1", "w. brachten", "o. für ihre Herren"] },
      { number: 6, text: "Und das Jeschana-Tor* besserten Jojada, der Sohn Paseachs, und Meschullam, der Sohn Besodjas, aus. Sie bauten es aus Balken und setzten seine Torflügel, seine Riegel und seine Sperrbalken ein.", footnotes: ["d. i. das »Alte Tor«, o. das Tor der Altstadt\n℘ Kap. 12,39"] },
      { number: 7, text: "Und ihnen zur Seite besserte Melatja, der Gibeoniter, aus und Jadon, der Meronotiter*, Männer aus Gibeon und Mizpa, die zum Amtsbereich* des Statthalters diesseits des Stromes* gehörten.", footnotes: ["℘ 1Chr 27,30", "w. zum Thron", "d. i. westlich des Euphrat"] },
      { number: 8, text: "Daneben* besserte Usiël, der Sohn Harhajas, aus, der Goldschmied*. Und ihm zur Seite besserte Hananja, der Salbenmischer*, aus. Und sie befestigten* Jerusalem bis an die breite Mauer*.", footnotes: ["w. an seiner Seite", "w. <ein Sohn> der Goldschmiede; d. h., der zur Zunft der Goldschmiede gehörte", "w. ein Sohn der Salbenmischer; d. h., der zur Zunft der Salbenmischer gehörte", "o. sie pflasterten", "℘ Kap. 12,38"] },
      { number: 9, text: "Und daneben* besserte Refaja, der Sohn Hurs, aus, der Oberste des halben Bezirks von Jerusalem.", footnotes: ["w. an ihrer Seite"] },
      { number: 10, text: "Und daneben* besserte Jedaja, der Sohn Harumafs, aus, und zwar seinem Haus gegenüber. Und ihm zur Seite besserte Hattusch*, der Sohn Haschabnejas, aus.", footnotes: ["w. an ihrer Seite", "℘ Kap. 10,5"] },
      { number: 11, text: "Einen weiteren Mauerabschnitt* besserten Malkija, der Sohn Harims*, und Haschub, der Sohn Pahat-Moabs*, aus, dazu den Ofenturm*.", footnotes: ["w. eine zweite abgemessene Strecke", "℘ Kap. 7,35", "℘ Kap. 7,11", "w. den Turm der Backöfen\n℘ Kap. 12,38"] },
      { number: 12, text: "Und daneben* besserte Schallum*, der Sohn des Lohesch, aus, der Oberste des <anderen> halben Bezirks von Jerusalem, er und seine Töchter.", footnotes: ["w. an ihrer Seite", "℘ Kap. 7,45"] },
      { number: 13, text: "Das Taltor* besserten Hanun und die Bewohner von Sanoach* aus. Sie bauten es und setzten seine Torflügel, seine Riegel und seine Sperrbalken ein und <bauten weiter> tausend Ellen an der Mauer bis zum Aschentor*.", footnotes: ["℘ Kap. 2,13", "℘ Kap. 11,30", "o. Misttor\n℘ Kap. 2,13"] },
      { number: 14, text: "Und das Aschentor* besserte Malkija, der Sohn Rechabs*, aus, der Oberste des Bezirks von Bet-Kerem*. Er baute es und setzte seine Torflügel, seine Riegel und seine Sperrbalken ein.", footnotes: ["o. Misttor\n℘ Kap. 2,13", "℘ 2Kö 10,15", "℘ Jer 6,1"] },
      { number: 15, text: "Und das Quelltor* besserte Schallun, der Sohn Kolhoses, der Oberste des Bezirks von Mizpa, aus. Er baute es und überdachte es und setzte seine Torflügel, seine Riegel und seine Sperrbalken ein. Und <er baute> die Mauer am Teich der Wasserleitung zum Königsgarten, und <zwar> bis zu den Stufen*, die von der Stadt Davids* hinabführen.", footnotes: ["℘ Kap. 2,14", "℘ Jes 8,6; Joh 9,7", "℘ 2Sam 5,7.9"] },
      { number: 16, text: "Nach ihm besserte Nehemja, der Sohn Asbuks, aus, der Oberste des halben Bezirks von Bet-Zur, bis <zu der Stelle> gegenüber den Gräbern Davids* und bis zu dem Teich*, der angelegt worden war, und bis zu dem Haus der Helden.", footnotes: ["℘ Apg 2,29", "℘ Kap. 2,14"] },
      { number: 17, text: "Nach ihm besserten die Leviten aus <unter> Rehum*, dem Sohn Banis*. Ihm zur Seite besserte Haschabja aus, der Oberste des halben Bezirks von Keïla*, für seinen Bezirk.", footnotes: ["℘ Kap. 12,3", "℘ Kap. 9,4.5", "℘ 1Sam 23,1"] },
      { number: 18, text: "Nach ihm besserten ihre Brüder <unter> Binnui* aus, dem Sohn Henadads, dem Obersten des <anderen> halben Bezirks von Keïla*.", footnotes: ["so mit 2 hebr. Handschr., mehreren LXX-Handschr. und der syr. Üs.; Mas. T.: Bawai", "℘ 1Sam 23,1"] },
      { number: 19, text: "Und ihm zur Seite besserte Eser, der Sohn Jeschuas, der Oberste von Mizpa, einen weiteren Mauerabschnitt* aus, gegenüber dem Aufgang zum Zeughaus am Winkel*.", footnotes: ["w. eine zweite abgemessene Strecke", "℘ 2Chr 26,9"] },
      { number: 20, text: "Nach ihm besserte Baruch, der Sohn Sabbais*, eifrig einen weiteren Mauerabschnitt* aus, <und zwar> vom Winkel bis zum Eingang des Hauses des Hohenpriesters Eljaschib*.", footnotes: ["℘ Esr 10,28", "w. eine zweite abgemessene Strecke", "℘ V. 1"] },
      { number: 21, text: "Nach ihm besserte Meremot, der Sohn Urias, des Sohnes des Hakkoz*, einen weiteren Mauerabschnitt* aus, vom Eingang des Hauses Eljaschibs bis zum Ende des Hauses Eljaschibs*.", footnotes: ["℘ V. 4", "w. eine zweite abgemessene Strecke", "℘ V. 1"] },
      { number: 22, text: "Und nach ihm besserten die Priester aus, die Männer <aus> der <Jordan>ebene*.", footnotes: ["w. der Umgebung <des Jordan>\n℘ Kap. 12,28"] },
      { number: 23, text: "Daran anschließend* besserten Benjamin und Haschub ihrem Haus gegenüber aus. Daran anschließend* besserte Asarja, der Sohn Maasejas, des Sohnes Ananjas, neben seinem Haus aus.", footnotes: ["w. Nach ihm", "w. Nach ihm"] },
      { number: 24, text: "Nach ihm besserte Binnui, der Sohn Henadads*, einen weiteren Mauerabschnitt* aus, vom Haus Asarjas an bis an den Winkel und <weiter> bis an die Ecke.", footnotes: ["℘ Kap. 10,10; Esr 3,9", "w. eine zweite abgemessene Strecke"] },
      { number: 25, text: "Palal, der Sohn Usais, <besserte> gegenüber dem Winkel und dem oberen Turm <aus>, der beim Wachthof* am Haus des Königs vorspringt*. Nach ihm <besserte> Pedaja, der Sohn des Parosch*, <aus> —", footnotes: ["℘ Kap. 12,39; Jer 32,2; Mi 4,8", "o. und dem Turm <aus>, der vom oberen Haus des Königs vorspringt", "℘ Esr 2,3"] },
      { number: 26, text: "aber die Tempeldiener* wohnten auf dem Ofel* — bis <zu der Stelle> gegenüber dem Wassertor* im Osten und dem vorspringenden Turm. —", footnotes: ["℘ Esr 2,43", "w. Buckel; d. i. ein Hügel südlich des Tempelberges\n℘ Kap. 11,21; 2Chr 27,3; Jes 32,14", "℘ Kap. 8,1.3; 12,37"] },
      { number: 27, text: "Nach ihm besserten die Tekoïter* einen weiteren Mauerabschnitt* aus, von <der Stelle> gegenüber dem großen vorspringenden Turm an bis zur Mauer des Ofel*.", footnotes: ["℘ V. 5", "w. eine zweite abgemessene Strecke", "w. Buckel; d. i. ein Hügel südlich des Tempelberges"] },
      { number: 28, text: "Oberhalb des Rosstores* besserten die Priester aus, jeder seinem Haus gegenüber.", footnotes: ["℘ 2Kö 11,16; Jer 31,40"] },
      { number: 29, text: "Nach ihnen besserte Zadok, der Sohn Immers*, aus, seinem Haus gegenüber. Und nach ihm besserte Schemaja, der Sohn Schechanjas, der Hüter des Osttores, aus.", footnotes: ["℘ Kap. 7,40"] },
      { number: 30, text: "Nach ihm besserten Hananja, der Sohn Schelemjas, und Hanun, der sechste Sohn Zalafs, einen weiteren Mauerabschnitt aus. Nach ihm besserte Meschullam*, der Sohn Berechjas, aus, seiner <Tempel>zelle gegenüber.", footnotes: ["℘ V. 4"] },
      { number: 31, text: "Nach ihm besserte Malkija, von den Goldschmieden*, aus, bis an das Haus der Tempeldiener und der Händler, dem Tor Mifkad* gegenüber und bis an das Obergemach an der <Mauer>ecke.", footnotes: ["w. ein Sohn der Goldschmiedezunft", "d. h. dem Wachttor"] },
      { number: 32, text: "Und zwischen dem Obergemach an der Ecke und dem Schaftor besserten die Goldschmiede und die Händler aus." },
      { number: 33, text: "Und es geschah, als Sanballat hörte, dass wir die Mauer bauten*, da wurde er zornig und ärgerte sich sehr*. Und er spottete über die Juden*.", heading: "Bau der Mauer trotz Widerstand der feindlichen Umgebung", footnotes: ["℘ Kap. 4,1; Esr 4,1", "℘ Kap. 2,10", "℘ Kap. 2,19; Ps 79,4"] },
      { number: 34, text: "Und er sprach vor seinen Brüdern und zu der Oberschicht von Samaria und sagte: Was machen die ohnmächtigen Juden? Wollen sie <Jerusalem> für sich befestigen*? Wollen sie <zum Opfer> schlachten*? Wollen sie es heute vollenden? Wollen sie die Steine aus den Schutthaufen wieder zum Leben bringen? Sie sind doch verbrannt*!", footnotes: ["o. pflastern", "℘ Kap. 12,43", "℘ Jes 61,4; Hes 36,10.33; Am 9,11.14"] },
      { number: 35, text: "Und Tobija*, der Ammoniter, <stand> neben ihm und sagte: Was sie auch bauen mögen — wenn ein Fuchs <daran> hinaufspringt, reißt er ihre Steinmauer ein! —", footnotes: ["℘ Kap. 2,10"] },
      { number: 36, text: "Höre, unser Gott*, wie wir zum Gespött geworden sind*, und lass ihre Schmähung auf ihren Kopf zurückkommen* und gib sie der Plünderung preis in einem Land der Gefangenschaft!", footnotes: ["℘ 2Kö 19,4", "℘ Ps 123,3.4", "℘ Ps 7,17; 79,12"] },
      { number: 37, text: "Und decke ihre Schuld nicht zu, und ihre Sünde werde vor deinem Angesicht nicht ausgelöscht*! Denn sie haben in den Bauenden <dich zum Zorn> gereizt*. —", footnotes: ["℘ Ps 69,28.29; Jer 15,15; 2Tim 4,14", "o. sie haben die Bauenden <beleidigt>"] },
      { number: 38, text: "Wir aber bauten die Mauer <weiter> auf, so dass die ganze Mauer bis zur Hälfte* geschlossen werden konnte, und das Volk war mit <ganzem> Herzen an der Arbeit*.", footnotes: ["d. h. bis zur halben Höhe", "℘ Esr 4,12"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und es geschah, als Sanballat und Tobija und die Araber, Ammoniter und Aschdoditer hörten, dass <die> Ausbesserung* an den Mauern Jerusalems Fortschritte machte*, weil die Breschen sich zu schließen begannen, da wurden sie sehr zornig*.", footnotes: ["w. Heilung <der Schäden>", "℘ Kap. 3,33", "℘ Kap. 2,10.19"] },
      { number: 2, text: "Und sie schlossen sich zusammen, alle miteinander, um zu kommen und gegen Jerusalem zu kämpfen und darin Verwirrung anzurichten*.", footnotes: ["℘ Esr 4,4.5; Ps 83,4-6"] },
      { number: 3, text: "Da beteten* wir zu unserem Gott und stellten eine Wache gegen sie auf*, Tag und Nacht <zum Schutz> vor ihnen.", footnotes: ["o. flehten", "℘ Mt 26,41; Lk 21,36"] },
      { number: 4, text: "Und <das Volk von> Juda sagte: Die Kraft der Lastträger schwindet*, und es ist <noch so> viel Schutt da. Wir allein schaffen es nicht <mehr>, an der Mauer zu bauen.", footnotes: ["w. stürzt"] },
      { number: 5, text: "Unsere Bedränger aber sagten <sich>: Sie sollen es nicht erkennen und sollen nichts <von uns> sehen, bis wir mitten unter sie gekommen sind und sie erschlagen und das Werk zum Stillstand bringen*.", footnotes: ["℘ 2Sam 17,2"] },
      { number: 6, text: "Und es geschah, als die Juden, die neben ihnen wohnten, kamen und uns <wohl> zehnmal sagten: Von allen Orten, wohin ihr euch <auch> wenden mögt, <sind sie> gegen uns!* —", footnotes: ["Andere üs. mit Textänderung: uns <wohl> zehnmal all die Anschläge verrieten, die man gegen uns plante,"] },
      { number: 7, text: "da stellte ich an Stellen, die niedriger waren als der Platz hinter der Mauer, an den offenen Stellen* — da stellte ich das Volk auf, nach Sippen <geordnet> mit ihren Schwertern, ihren Lanzen und ihren Bogen.", footnotes: ["Andere üs. mit Textänderung: da stellte ich Speerbewaffnete hinter der Mauer an den offenen Stellen auf"] },
      { number: 8, text: "Und als ich <ihre Furcht> sah, da machte ich mich auf und sagte zu den Edlen* und zu den Vorstehern und zum Rest des Volkes: Fürchtet euch nicht vor ihnen!* An den Herrn denkt, den großen und furchtbaren*! Und kämpft für eure Brüder, eure Söhne und eure Töchter, eure Frauen und eure Häuser!*", footnotes: ["w. Freigeborenen", "℘ 5Mo 1,29; 2Chr 32,7; Dan 9,25", "℘ Kap. 1,5", "℘ 2Sam 10,12"] },
      { number: 9, text: "Und es geschah, als unsere Feinde hörten, dass es uns bekannt geworden war und dass Gott ihren Rat zunichte gemacht hatte*, da konnten wir alle zur Mauer zurückkehren, jeder an sein Werk.", footnotes: ["℘ Hi 5,12; Ps 33,10; Spr 22,12"] },
      { number: 10, text: "Und es geschah von diesem Tag an: Die <eine> Hälfte meiner jungen Männer war an dem Werk beschäftigt, und ihre <andere> Hälfte hielt die Speere, die Schilde und die Bogen und die Schuppenpanzer <bereit>. Und die Obersten <standen> hinter dem ganzen Haus Juda," },
      { number: 11, text: "das an der Mauer baute. Und die Lastträger trugen <ihre> Last <folgendermaßen>*: Mit der einen Hand arbeiteten sie* am Werk, während die andere die Waffe hielt.", footnotes: ["LXX: Und die Lastträger waren kriegsmäßig gegliedert", "w. arbeitete er; 2 hebr. Handschr.: Und seine eine Hand arbeitete"] },
      { number: 12, text: "Und von den Bauleuten hatte jeder sein Schwert um seine Hüften gegürtet, so bauten sie. Und der ins Horn zu stoßen hatte, war neben mir. —" },
      { number: 13, text: "Und ich sagte zu den Edlen* und zu den Vorstehern und zum Rest des Volkes: Das Werk ist groß und weitläufig*, und wir sind auf der Mauer zerstreut, jeder weitab von seinen Brüdern.", footnotes: ["w. Freigeborenen", "℘ Kap. 6,3"] },
      { number: 14, text: "An den Ort, woher ihr den Schall des Horns hört*, dorthin sammelt euch zu uns! Unser Gott wird für uns kämpfen*!", footnotes: ["℘ Ri 3,27", "℘ 2Mo 14,14; Dan 11,32; Sach 14,3"] },
      { number: 15, text: "So arbeiteten wir an dem Werk — die Hälfte von ihnen hielt die Lanzen bereit — vom Aufgang der Morgenröte an, bis die Sterne hervortraten." },
      { number: 16, text: "Zu derselben Zeit sagte ich auch zum Volk: Jeder soll mit seinem Helfer* die Nacht über innerhalb Jerusalems bleiben, so dass sie uns nachts als Wache dienen und tagsüber am Werk.", footnotes: ["w. Jungen"] },
      { number: 17, text: "Und weder ich noch meine Brüder, noch meine Diener, noch die Männer der Wache*, die in meinem Gefolge waren* — wir zogen unsere Kleider nicht aus. Jeder hatte seine Waffe zu seiner Rechten*.", footnotes: ["℘ Hl 3,8", "w. die hinter mir waren", "T.; Mas. T.: Jeder <ging mit> seiner Waffe <selbst> zum Wasser"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und es entstand ein großes Geschrei <der Leute aus> dem Volk und ihrer Frauen gegen ihre jüdischen Brüder*.", heading: "Schuldenerlass — Nehemias Selbstlosigkeit", footnotes: ["℘ Jes 5,7; Mal 2,13"] },
      { number: 2, text: "Da gab es solche, die sagten: Unsere Söhne und unsere Töchter — wir sind viele! Wir wollen Getreide bekommen*, damit wir essen und leben können!*", footnotes: ["Andere lesen mit Textänderung: Unsere Söhne und unsere Töchter müssen wir verpfänden, damit wir Getreide bekommen", "℘ 1Mo 47,19"] },
      { number: 3, text: "Und es gab solche, die sagten: Wir mussten unsere Felder und unsere Weinberge und unsere Häuser verpfänden, damit wir in der Hungersnot Getreide bekamen*.", footnotes: ["℘ V. 11; 3Mo 25,35-37"] },
      { number: 4, text: "Und es gab solche, die sagten: Wir haben für die Steuer des Königs Geld geliehen auf unsere Felder und unsere Weinberge." },
      { number: 5, text: "Und nun, unser Fleisch <und Blut ist doch> wie das Fleisch <und Blut> unserer Brüder, unsere Kinder sind wie ihre Kinder. Und siehe, wir müssen unsere Söhne und unsere Töchter zu Sklaven erniedrigen. Und manche von unseren Töchtern sind <schon> erniedrigt worden, und wir sind machtlos <dagegen>*. Unsere Felder und unsere Weinberge gehören ja den andern.", footnotes: ["w. und es gibt nichts für die Kraft unserer Hände<, dagegen etwas zu tun>\n℘ 2Mo 21,7; Spr 22,7"] },
      { number: 6, text: "Da wurde ich sehr zornig*, als ich ihr Klagegeschrei und diese Worte hörte.", footnotes: ["℘ Kap. 13,8.17.25; Ps 119,53; Jak 2,6"] },
      { number: 7, text: "Und mein Herz in mir ging mit sich zu Rate, und ich klagte die Edlen* und die Vorsteher an und sagte zu ihnen: Ihr treibt Wucher an euren Brüdern*! Und ich veranstaltete eine große Versammlung gegen sie*.", footnotes: ["w. Freigeborenen", "w. Eine Schuldforderung fordert ihr jeder von seinem Bruder\n℘ 2Mo 22,24", "o. ihretwegen"] },
      { number: 8, text: "Und ich sagte zu ihnen: Wir haben unsere Brüder, die Juden, die an die Nationen verkauft waren, so weit es uns möglich war, <frei>gekauft. Und ihr wollt eure Brüder sogar verkaufen, damit sie <dann wieder> an uns verkauft werden*?* Da schwiegen sie und fanden keine Antwort.", footnotes: ["o. und sie sollen sich an uns verkaufen", "℘ 3Mo 25,47.48"] },
      { number: 9, text: "Und ich sagte: Nicht gut ist die Sache, die ihr da tut! Solltet ihr nicht in der Furcht unseres Gottes leben*, um dem Hohn der Nationen, unserer Feinde, zu entgehen?*", footnotes: ["w. gehen", "℘ 2Sam 12,14; Tit 2,8"] },
      { number: 10, text: "Aber auch ich <und> meine Brüder und meine Diener, wir haben ihnen Geld und Getreide geliehen. Erlassen wir <ihnen> doch diese Schuldforderung*!", footnotes: ["℘ Kap. 10,32; 5Mo 15,2; Hes 18,7-9"] },
      { number: 11, text: "Gebt ihnen doch gleich heute ihre Felder, ihre Weinberge, ihre Olivengärten und ihre Häuser zurück! Und <erlasst ihnen> die Schuldforderung an* Geld und Getreide, an Most und Öl, das ihr ihnen geliehen habt*!", footnotes: ["T.; Mas. T.: und <erlasst ihnen> den hundertsten <Teil> vom", "℘ Jes 58,6"] },
      { number: 12, text: "Da sagten sie: Wir wollen es zurückgeben und nichts von ihnen fordern. Wir wollen so handeln, wie du es gesagt hast. Und ich rief die Priester und ließ sie* schwören, nach diesem Wort zu handeln*.", footnotes: ["d. h. die Edlen und die Vorsteher", "℘ Kap. 10,30; Esr 10,5"] },
      { number: 13, text: "Auch schüttelte ich meinen Gewandbausch aus* und sprach: Ebenso soll Gott jeden Mann aus seinem Haus und aus seinem Besitz hinausschütteln, der dieses Wort nicht hält! Er sei ebenso ausgeschüttelt und leer! Und die ganze Versammlung sprach: Amen*! Und sie lobten den HERRN. Und das Volk handelte nach diesem Wort.", footnotes: ["℘ Spr 28,4; Apg 18,6", "℘ Kap. 8,6; 2Kö 23,3"] },
      { number: 14, text: "Auch habe ich von dem Tag an, an dem der König* mich beauftragt hatte, im Land Juda ihr Statthalter zu sein, mit meinen Brüdern nicht das Brot des Statthalters gegessen*, <und zwar> vom 20. Jahr bis zum 32. Jahr des Königs Artahsasta, zwölf Jahre lang*.", footnotes: ["w. er", "d. h. er verzichtete auf die Abgaben, die ihm als Statthalter von der Bevölkerung zustanden", "℘ Kap. 13,6; 1Kor 9,4.12"] },
      { number: 15, text: "Aber die früheren Statthalter, die vor mir gewesen waren, hatten auf das Volk <schwere> Lasten gelegt* und <Abgaben> für Brot und Wein von ihnen genommen, dazu <noch> vierzig Schekel Silber*. Auch ihre Diener hatten willkürlich über das Volk geherrscht. Ich aber, ich machte <es> nicht so*, aus Furcht vor Gott*.", footnotes: ["℘ Kla 5,8", "Vulg.: und für Brot und Wein von ihnen vierzig Schekel Silber an jedem Tag genommen", "℘ 2Kor 11,9", "℘ 1Mo 42,18"] },
      { number: 16, text: "Und auch beim Werk an dieser Mauer packte ich mit an. Ein Feld haben wir nicht gekauft. Alle meine Diener waren dort zum Werk versammelt." },
      { number: 17, text: "Und die Juden, sowohl die Vorsteher — 150 Mann — als auch die, die von den Nationen rings um uns herum zu uns kamen, waren an meinem Tisch*.", footnotes: ["℘ Röm 12,13"] },
      { number: 18, text: "Und was für jeden Tag zubereitet wurde, war: ein Rind, sechs auserlesene Schafe und Geflügel wurden mir zubereitet* und alle zehn Tage von allerlei Wein die Fülle. Und trotzdem forderte ich nicht das Brot des Statthalters*, denn der Dienst lastete schwer <genug> auf diesem Volk.", footnotes: ["℘ 1Kö 5,3", "d. h. er verzichtete auf die Abgaben, die ihm als Statthalter von der Bevölkerung zustanden"] },
      { number: 19, text: "Gedenke, mein Gott*, mir zugute*, all dessen, was ich für dieses Volk getan habe!", footnotes: ["℘ Kap. 13,14.22", "℘ Kap. 13,31"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und es geschah, als Sanballat und Tobija und Geschem, der Araber, und der Rest unserer Feinde* vernahmen, dass ich die Mauer gebaut hatte* und dass kein Riss mehr darin war — doch hatte ich bis zu dieser Zeit die Torflügel noch nicht in die Tore eingesetzt —,", heading: "Mordpläne gegen Nehemia — Vollendung der Mauer", footnotes: ["℘ Kap. 2,10.19", "℘ Kap. 7,1"] },
      { number: 2, text: "da sandten Sanballat und Geschem zu mir <und ließen mir> sagen: Komm, wir wollen uns in Kefirim, im Tal von Ono*, treffen! Sie beabsichtigten aber, mir Böses anzutun*.", footnotes: ["℘ Kap. 11,35; 1Chr 8,12", "℘ Spr 26,24.25"] },
      { number: 3, text: "Und ich sandte Boten zu ihnen <und ließ ihnen> sagen: Ich führe gerade ein großes Werk aus* und kann nicht hinabkommen. Warum sollte das Werk ruhen*, wenn ich es zurückließe und zu euch hinabkäme?", footnotes: ["℘ Kap. 4,13", "℘ Joh 9,4"] },
      { number: 4, text: "Und sie sandten auf diese Weise viermal zu mir, ich aber erwiderte ihnen <viermal> auf dieselbe Weise." },
      { number: 5, text: "Da sandte Sanballat zum fünften Mal auf diese Weise seinen Diener zu mir; der hatte einen offenen Brief in seiner Hand," },
      { number: 6, text: "in dem stand geschrieben: Unter den Nationen verlautet, und Geschem sagt es <auch>: Du und die Juden, ihr beabsichtigt, euch zu empören*. Darum baust du die Mauer auf. Und du willst nach diesem Gerücht ihr König werden.", footnotes: ["℘ Kap. 2,19; Esr 4,12.13"] },
      { number: 7, text: "Sogar Propheten sollst du eingesetzt haben, damit sie in Jerusalem über dich ausrufen: <Er ist> König in Juda! Nun, solche Gerüchte werden dem König zu Ohren kommen. So mach dich nun auf, dass wir miteinander beraten!" },
      { number: 8, text: "Da sandte ich zu ihm <und ließ ihm> sagen: Es ist nichts geschehen von diesen Dingen, die du behauptest, sondern aus deinem Herzen hast du sie <frei> erfunden." },
      { number: 9, text: "Denn sie alle wollten uns in Furcht versetzen, indem sie <sich> sagten: Ihre Hände werden von dem Werk ablassen, und es wird nicht ausgeführt werden*. — Und nun, stärke meine Hände!*", footnotes: ["℘ 2Chr 32,18; Esr 4,4", "o. Nun aber stärkte ich meine Hände.\n℘ Jes 40,29"] },
      { number: 10, text: "Und ich kam in das Haus Schemajas, des Sohnes Delajas, des Sohnes Mehetabels, der sich eingeschlossen hatte*. Der sagte: Wir wollen uns im Haus Gottes treffen, im Innern des Tempelraums und die Türen des Tempelraums verschließen. Denn sie wollen kommen, um dich umzubringen; und zwar kommen sie in der Nacht, um dich umzubringen*.", footnotes: ["d. i. vielleicht wegen eines Gelübdes; andere üs.: der <wegen Unreinheit> verhindert war; d. h. er musste aus kultischen Gründen eine gewisse Zeit isoliert leben; vgl. Jer 36,5", "℘ Lk 13,31"] },
      { number: 11, text: "Ich aber sagte: Ein Mann wie ich sollte davonlaufen*? Und wer von meinesgleichen könnte in den Tempel hineingehen und am Leben bleiben*? Ich gehe nicht mit hinein!", footnotes: ["℘ Ps 11,1; Spr 28,1; Apg 20,24", "o. wer in meiner Stellung darf in den Tempel gehen, um leben zu bleiben\n℘ 4Mo 3,10.38"] },
      { number: 12, text: "Und ich merkte: Nein, nicht Gott hatte ihn gesandt, sondern er redete die Prophezeiung über mich, weil Tobija und Sanballat ihn angeheuert hatten*.", footnotes: ["℘ Hes 13,7"] },
      { number: 13, text: "Dazu war er angeheuert worden, dass ich aus Furcht so handeln und mich versündigen sollte. So hätten sie <einen Anlass> zur üblen Nachrede gehabt, damit man mich schmähen könnte*. —", footnotes: ["℘ 1Petr 3,16"] },
      { number: 14, text: "Gedenke es, mein Gott*, dem Tobija und dem Sanballat nach diesen ihren Taten und auch der Prophetin Noadja* und dem Rest der Propheten, die mich in Furcht versetzen wollten!", footnotes: ["℘ Kap. 13,29; Ps 137,7", "℘ 2Mo 15,20"] },
      { number: 15, text: "Und die Mauer wurde am 25. des <Monats> Elul*, in 52 Tagen fertiggestellt*.", footnotes: ["d. i. der sechste Monat des bürgerlichen Jahres (Februar/März)", "℘ Esr 6,14.15"] },
      { number: 16, text: "Und es geschah, als alle unsere Feinde es hörten, da fürchteten sich alle Nationen, die rings um uns her waren, und unsere Feinde* sanken sehr in ihren Augen*. Und sie erkannten, dass dieses Werk von unserem Gott aus geschehen war*.", footnotes: ["w. sie", "℘ Jos 2,9; Ps 129,5", "℘ Ps 109,27; 147,2"] },
      { number: 17, text: "In denselben Tagen ließen auch <einige der> Edlen* von Juda viele Briefe an Tobija abgehen, und solche von Tobija kamen an sie.", footnotes: ["w. Freigeborenen"] },
      { number: 18, text: "Denn es gab viele in Juda, die sich ihm mit einem Eid verbunden hatten*, denn er war ein Schwiegersohn Schechanjas, des Sohnes Arachs*. Und sein Sohn Johanan hatte die Tochter Meschullams, des Sohnes Berechjas*, <zur Frau> genommen.", footnotes: ["w. die Herren eines Eides für ihn waren", "℘ Kap. 7,10; Esr 2,5", "℘ Kap. 3,4.30"] },
      { number: 19, text: "Auch sprachen sie vor mir von seinen guten Taten* und hinterbrachten ihm meine Worte. <Und> Tobija sandte Briefe, um mich in Furcht zu versetzen.", footnotes: ["o. Eigenschaften; o. Absichten"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und es geschah, als die Mauer <fertig> gebaut war* und ich die Torflügel eingesetzt hatte, wurden die Torhüter und die Sänger und die Leviten bestimmt*.", heading: "Bestellung der Torhüter — Verzeichnis der Rückkehrer", footnotes: ["℘ Kap. 6,1", "℘ 1Chr 23,24; 25,26"] },
      { number: 2, text: "Dann übertrug ich den Oberbefehl über Jerusalem meinem Bruder Hanani* und dem Burgobersten Hananja; denn der <galt> als ein treuer Mann* und als gottesfürchtig vor vielen <anderen>*.", footnotes: ["℘ Kap. 1,2", "w. Mann der Wahrheit, o. Mann der Treue", "℘ 2Mo 18,21; 1Kö 18,3"] },
      { number: 3, text: "Und ich sagte zu ihnen: Die Tore Jerusalems sollen nicht eher geöffnet werden, als bis die Sonne heiß scheint. Und während sie <noch am Himmel> steht*, soll man die Torflügel schließen. Und <dann> verriegelt sie. Und man soll Wachen aus den Bewohnern Jerusalems aufstellen, den einen auf seiner Wache und den anderen vor seinem Haus*.", footnotes: ["T.; Mas. T.: und <so lange> bis sie dastehen", "o. jeden auf seine Wache, und <zwar> jeden gegenüber seinem Haus"] },
      { number: 4, text: "Die Stadt aber war nach allen Seiten hin weit ausgedehnt und groß, doch das Volk in ihr war spärlich*, und keine Häuser waren gebaut*.", footnotes: ["℘ Kap. 11,1.2", "o. und es waren <noch> nicht <genügend> Familien gegründet"] },
      { number: 5, text: "Und mein Gott gab mir es ins Herz, und ich versammelte die Edlen* und die Vorsteher und das Volk, damit sie sich registrieren ließen*. Und ich fand das Buch mit dem Geschlechtsregister derer, die zuerst heraufgezogen waren, und fand darin geschrieben:", footnotes: ["w. Freigeborenen", "nämlich zur Feststellung ihrer Abstammung\n℘ 1Chr 9,1"] },
      { number: 6, text: "*Das sind die Einwohner* der Provinz* <Juda>, die aus der Gefangenschaft hinaufzogen, die Weggeführten, die Nebukadnezar, der König von Babel, weggeführt hatte und die nach Jerusalem und Juda zurückgekehrt sind, jeder in seine Stadt,", footnotes: ["℘ V. 6-72: Esr 2,1-70", "w. die Söhne", "d. i. der persische Verwaltungsbezirk Juda"] },
      { number: 7, text: "<alle>, die mit Serubbabel kamen <und mit> Jeschua, Nehemja, Asarja, Raamja, Nahamani, Mordochai, Bilschan, Misperet, Bigwai, Nehum <und> Baana. <Das ist die> Zahl der Männer des Volkes Israel:" },
      { number: 8, text: "Die Söhne Parosch 2 172;" },
      { number: 9, text: "die Söhne Schefatja 372;" },
      { number: 10, text: "die Söhne Arach* 652;", footnotes: ["℘ Kap. 6,18"] },
      { number: 11, text: "die Söhne Pahat-Moab*, von den Söhnen Jeschuas und Joabs 2 818;", footnotes: ["℘ Kap. 3,11"] },
      { number: 12, text: "die Söhne Elam 1 254;" },
      { number: 13, text: "die Söhne Sattu 845;" },
      { number: 14, text: "die Söhne Sakkai 760;" },
      { number: 15, text: "die Söhne Binnui 648;" },
      { number: 16, text: "die Söhne Bebai 628;" },
      { number: 17, text: "die Söhne Asgad 2 322;" },
      { number: 18, text: "die Söhne Adonikam 667;" },
      { number: 19, text: "die Söhne Bigwai 2 067;" },
      { number: 20, text: "die Söhne Adin 655;" },
      { number: 21, text: "die Söhne Ater, von Hiskia, 98;" },
      { number: 22, text: "die Söhne Haschum 328;" },
      { number: 23, text: "die Söhne Bezai 324;" },
      { number: 24, text: "die Söhne Harif 112;" },
      { number: 25, text: "die Söhne Gibeon* 95;", footnotes: ["d. h. vielleicht: die Gibeoniter"] },
      { number: 26, text: "die Männer von Bethlehem und Netofa* 188;", footnotes: ["℘ Kap. 12,28; 2Sam 23,28.29"] },
      { number: 27, text: "die Männer von Anatot 128;" },
      { number: 28, text: "die Männer von Bet-Asmawet* 42;", footnotes: ["℘ Kap. 12,29"] },
      { number: 29, text: "die Männer von Kirjat-Jearim, Kefira und Beerot 743;" },
      { number: 30, text: "die Männer von Rama und Geba* 621;", footnotes: ["℘ Kap. 12,29"] },
      { number: 31, text: "die Männer von Michmas 122;" },
      { number: 32, text: "die Männer von Bethel* und Ai 123;", footnotes: ["℘ Kap. 11,31"] },
      { number: 33, text: "die Männer vom anderen Nebo* 52;", footnotes: ["LXX liest mit Esr 2,29: die Söhne Nebo"] },
      { number: 34, text: "die Söhne des anderen* Elam 1 254;", footnotes: ["vgl. V. 12"] },
      { number: 35, text: "die Söhne Harim* 320;", footnotes: ["℘ Kap. 3,11"] },
      { number: 36, text: "die Söhne* Jerichos 345;", footnotes: ["d. h. die Männer von"] },
      { number: 37, text: "die Söhne* Lod, Hadid und Ono 721;", footnotes: ["d. h. die Männer von"] },
      { number: 38, text: "die Söhne Senaa* 3 930.", footnotes: ["℘ Kap. 3,3"] },
      { number: 39, text: "Die Priester*: die Söhne Jedaja, vom Haus Jeschua 973;", footnotes: ["℘ Kap. 11,3"] },
      { number: 40, text: "die Söhne Immer* 1 052;", footnotes: ["℘ Kap. 3,29"] },
      { number: 41, text: "die Söhne Paschhur 1 247;" },
      { number: 42, text: "die Söhne Harim 1 017." },
      { number: 43, text: "Die Leviten*: die Söhne Jeschua von Kadmiël*, von den Söhnen* Hodewa* 74. —", footnotes: ["℘ Kap. 11,3", "℘ Kap. 10,10; 12,8", "Andere lesen mit einer griech. Üs.: Kadmiël, Binnui und", "mit Esr 2,40: Hodawja"] },
      { number: 44, text: "Die Sänger: die Söhne Asaf 148. —" },
      { number: 45, text: "Die Torhüter: die Söhne Schallum*, die Söhne Ater, die Söhne Talmon, die Söhne Akkub, die Söhne Hatita, die Söhne Schobai, <insgesamt> 138.", footnotes: ["℘ Kap. 3,12"] },
      { number: 46, text: "Die Tempeldiener*: die Söhne Ziha, die Söhne Hasufa, die Söhne Tabbaot,", footnotes: ["℘ Kap. 11,3"] },
      { number: 47, text: "die Söhne Keros, die Söhne Sia, die Söhne Padon," },
      { number: 48, text: "die Söhne Lebana, die Söhne Hagaba, die Söhne Salmai," },
      { number: 49, text: "die Söhne Hanan, die Söhne Giddel, die Söhne Gahar," },
      { number: 50, text: "die Söhne Reaja, die Söhne Rezin, die Söhne Nekoda," },
      { number: 51, text: "die Söhne Gasam, die Söhne Usa, die Söhne Paseach," },
      { number: 52, text: "die Söhne Besai, die Söhne der Mëuniter, die Söhne der Nefusiter," },
      { number: 53, text: "die Söhne Bakbuk, die Söhne Hakufa, die Söhne Harhur," },
      { number: 54, text: "die Söhne Bazlit, die Söhne Mehida, die Söhne Harscha," },
      { number: 55, text: "die Söhne Barkos, die Söhne Sisera, die Söhne Temach," },
      { number: 56, text: "die Söhne Neziach, die Söhne Hatifa." },
      { number: 57, text: "Die Söhne der Knechte Salomos*: die Söhne Sotai, die Söhne Soferet, die Söhne Perida*,", footnotes: ["℘ Kap. 11,3", "mit Esr 2,55: Peruda"] },
      { number: 58, text: "die Söhne Jaala, die Söhne Darkon, die Söhne Giddel," },
      { number: 59, text: "die Söhne Schefatja, die Söhne Hattil, die Söhne Pocheret-Zebajim, die Söhne Amon." },
      { number: 60, text: "Alle Tempeldiener und Söhne der Knechte Salomos waren 392." },
      { number: 61, text: "Und die folgenden sind <die>, die aus Tel-Melach, Tel-Harscha, Kerub-Addon und Immer heraufzogen — aber sie konnten ihr Vaterhaus und ihre Abstammung* nicht angeben, ob sie aus Israel wären —:", footnotes: ["o. ihr Vaterhaus und dessen Nachkommenschaft; w. das Haus ihrer Väter und ihren Samen"] },
      { number: 62, text: "die Söhne Delaja, die Söhne Tobija, die Söhne Nekoda 642." },
      { number: 63, text: "Und von den Priestern: die Söhne Habaja, die Söhne Hakkoz*, die Söhne Barsillai, der von den Töchtern des Gileaditers Barsillai eine Frau genommen hatte und nach dessen Namen* genannt wurde.", footnotes: ["℘ Kap. 3,4", "T.; Mas. T.: nach deren Namen; d. h. denen der Priester"] },
      { number: 64, text: "Diese suchten ihre Eintragung ins Geschlechtsregister, aber sie wurde nicht gefunden. So wurden sie vom Priesteramt als unrein ausgeschlossen." },
      { number: 65, text: "Und der Tirschata* befahl ihnen, nicht vom Hochheiligen zu essen, bis der Priester* für die Urim und die Tummim* auftrete.", footnotes: ["d. i. der Statthaltertitel Nehemias", "mit Esr 2,63: bis ein Priester", "℘ 2Mo 28,30"] },
      { number: 66, text: "Die ganze Versammlung <zählte> insgesamt 42 360," },
      { number: 67, text: "abgesehen von ihren Knechten und ihren Mägden; diese waren 7 337. Und sie hatten 245 Sänger und Sängerinnen*,", footnotes: ["Einige hebr. Handschr. und LXX haben aus Esr 2,66 hier eingefügt: Ihre Pferde waren 736, ihre Maultiere 245"] },
      { number: 68, text: "435 Kamele und 6 720 Esel." },
      { number: 69, text: "Und ein Teil der Familienoberhäupter* spendete für das Werk. Der Tirschata* gab für den Schatz 1 000 Golddariken, 50 Sprengschalen, 530 Priesterleibröcke.", footnotes: ["o. von den Sippenoberhäuptern; w. von den Häuptern der Väter", "d. i. der Statthaltertitel Nehemias"] },
      { number: 70, text: "Und einige von den Familienoberhäuptern* gaben für den Schatz des Werkes 20 000 Golddariken und 2 200 Silberminen.", footnotes: ["o. von den Sippenoberhäuptern; w. von den Häuptern der Väter"] },
      { number: 71, text: "Und was das übrige Volk gab, war 20 000 Golddariken und 2 000 Silberminen und 67 Priesterleibröcke." },
      { number: 72, text: "Und die Priester und die Leviten, die Torhüter und die Sänger, <einige> aus dem Volk und die Tempeldiener und ganz Israel ließen sich in ihren Städten nieder.Und als der siebte Monat* herankam und die Söhne Israel in ihren Städten <wohnten>,", heading: "Gesetzeslesung und Laubhüttenfest", footnotes: ["℘ Esr 3,1"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "da versammelte sich das ganze Volk wie ein Mann auf dem Platz, der vor dem Wassertor war*. Und sie sagten zu Esra, dem Schriftgelehrten*, er solle das Buch mit dem Gesetz des Mose herbeibringen, das der HERR <dem Volk> Israel geboten hatte.", footnotes: ["℘ Kap. 3,26", "℘ Kap. 12,26; Esr 7,6"] },
      { number: 2, text: "So brachte am ersten Tag des siebten Monats* der Priester Esra das Gesetz vor die Versammlung, vor Männer und Frauen, und vor jeden, der zu hören verstand*.", footnotes: ["℘ 3Mo 23,24; 4Mo 29,1", "℘ V. 18; Kap. 10,29; 13,1; 5Mo 31,9-13; Jos 8,35; Apg 10,33; 13,44"] },
      { number: 3, text: "Und er las daraus vor auf dem Platz, der vor dem Wassertor war, vom <ersten Tages>licht bis zum Mittag in Gegenwart der Männer und Frauen und <aller>, die es verstehen konnten. Und die Ohren des ganzen Volkes waren auf das Buch des Gesetzes <gerichtet>*.", footnotes: ["℘ V. 18; Kap. 10,29; 13,1; 5Mo 31,9-13; Jos 8,35; Apg 10,33; 13,44"] },
      { number: 4, text: "Und Esra, der Schriftgelehrte, stand auf einem Holzgerüst, das man zu diesem Zweck hergestellt hatte*. Und neben ihm standen Mattitja, Schema, Anaja, Uria, Hilkija und Maaseja, zu seiner Rechten; und zu seiner Linken Pedaja, Mischaël, Malkija, Haschum und Haschbaddana, Secharja <und> Meschullam.", footnotes: ["℘ Kap. 9,4; 2Chr 6,13"] },
      { number: 5, text: "Und Esra öffnete das Buch vor den Augen des ganzen Volkes, denn er überragte das ganze Volk. Und als er es öffnete, stand das ganze Volk auf." },
      { number: 6, text: "Und Esra pries den HERRN*, den großen Gott*, und das ganze Volk antwortete: Amen, Amen*! — wobei sie ihre Hände emporhoben*. Und sie verneigten sich und warfen sich vor dem HERRN nieder mit dem Gesicht zur Erde*.", footnotes: ["o. segnete den HERRN; o. dankte dem HERRN", "℘ 1Chr 29,20; 2Chr 6,4; 29,10; Ps 95,3", "℘ Kap. 5,13; 1Chr 29,10; 1Kor 14,16", "℘ Ps 134,2", "℘ 2Chr 20,18"] },
      { number: 7, text: "Und Jeschua und Bani* und Scherebja*, Jamin, Akkub, Schabbetai, Hodija, Maaseja, Kelita*, Asarja, Josabad, Hanan, Pelaja, die Leviten*, belehrten das Volk über das Gesetz*. Dabei <stand> das Volk an seiner Stelle*.", footnotes: ["℘ Kap. 9,4", "℘ Esr 8,18", "℘ Esr 10,23", "so mit mehreren LXX-Handschr. und Vulg.; Mas. T.: und die Leviten", "℘ 5Mo 33,10; 2Chr 17,9", "℘ 1Kö 8,14"] },
      { number: 8, text: "Und sie lasen aus dem Buch, aus dem Gesetz Gottes*, abschnittsweise* vor und gaben den Sinn an, so dass man das Vorgelesene verstehen konnte*.", footnotes: ["℘ Kap. 9,3; 2Kö 23,2", "o. mit <gleichzeitiger> Übersetzung; d. h. aus dem Hebräischen ins Aramäische", "o. und machten <so> das Vorgelesene verständlich\n℘ Lk 24,27.45"] },
      { number: 9, text: "Und Nehemia, das ist der Tirschata*, und der Priester Esra, der Schriftgelehrte, und die Leviten, die das Volk belehrten, sagten zum ganzen Volk: Dieser Tag ist dem HERRN, eurem Gott, heilig! Seid nicht traurig und weint nicht!* Denn das ganze Volk weinte, als es die Worte des Gesetzes hörte*.", footnotes: ["d. i. der Statthaltertitel Nehemias\n℘ Esr 2,63", "℘ 5Mo 12,12", "℘ 2Chr 34,19"] },
      { number: 10, text: "Und er sagte <weiter> zu ihnen: Geht hin, esst fette Speisen und trinkt süße Getränke und sendet dem Anteile, für den nichts zubereitet ist*! Denn der Tag ist unserm Herrn heilig. Und seid nicht bekümmert*, denn die Freude am HERRN, sie ist euer Schutz*!", footnotes: ["o. Portionen an den, der nichts besitzt\n℘ Est 9,22", "℘ 1Kö 8,66", "w. eure Bergfeste, o. Zufluchtsstätte\n℘ 1Chr 16,27; Ps 89,17-19; Jes 12,1-3; 49,5"] },
      { number: 11, text: "Und die Leviten beruhigten das ganze Volk, indem sie sagten: Seid still, denn der Tag ist heilig! Seid nicht bekümmert!" },
      { number: 12, text: "Da ging das ganze Volk hin, um zu essen und zu trinken und Anteile zu versenden und ein großes Freudenfest* zu begehen*. Denn sie hatten die Worte verstanden, die man ihnen mitgeteilt hatte*.", footnotes: ["w. eine große Freude", "℘ 1Chr 29,22", "℘ Jer 15,16"] },
      { number: 13, text: "Und am zweiten Tag versammelten sich die Familienoberhäupter* des ganzen Volkes, die Priester und die Leviten, zu Esra, dem Schriftgelehrten, und zwar um Einsicht in die Worte des Gesetzes zu gewinnen.", footnotes: ["o. die Häupter der Väter"] },
      { number: 14, text: "Da fanden sie im Gesetz, das der HERR durch Mose geboten hatte, geschrieben, dass die Söhne Israel an dem Fest im siebten Monat in Laubhütten wohnen sollten*,", footnotes: ["℘ 3Mo 23,34.42"] },
      { number: 15, text: "so dass sie verkündigten und durch all ihre Städte und durch Jerusalem den Ruf ergehen ließen: Geht hinaus auf das Gebirge und holt Zweige vom Olivenbaum und Zweige vom wilden Ölbaum und Myrtenzweige und Palmzweige und Zweige von dicht belaubten Bäumen, um Laubhütten zu machen, wie es geschrieben steht!" },
      { number: 16, text: "Da zog das Volk hinaus und brachte <die Zweige> herbei. Und sie machten sich Laubhütten, jeder auf seinem Dach oder in ihren Höfen, in den Höfen des Hauses Gottes, auf dem Platz am Wassertor und auf dem Platz am Tor Ephraim*.", footnotes: ["℘ Kap. 12,39; 2Kö 14,13"] },
      { number: 17, text: "Und die ganze Versammlung, <alle,> die aus der Gefangenschaft zurückgekehrt waren, machten Laubhütten und wohnten in den Hütten. Denn die Söhne Israel hatten es nicht <mehr> so gehalten seit den Tagen Josuas, des Sohnes Nuns*, bis auf jenen Tag. Und es war eine sehr große Freude*.", footnotes: ["℘ Jos 1,1", "℘ 2Chr 30,26"] },
      { number: 18, text: "Und man las aus dem Buch des Gesetzes Gottes Tag für Tag vor, vom ersten Tag bis zum letzten Tag*. Und sie feierten das Fest sieben Tage lang. Und am achten Tag <war> die Festversammlung nach der Vorschrift*.", footnotes: ["℘ V. 2", "℘ 3Mo 23,36"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und am 24. Tag dieses Monats versammelten sich die Söhne Israel unter Fasten* und in Sacktuch, und mit Erde auf ihrem Haupt*.", heading: "Bußgebet der Leviten", footnotes: ["℘ 2Chr 20,3.4; Esr 8,21", "w. und Erde war auf ihnen\n℘ Jos 7,6; Hi 2,12.13; Joe 2,12; Offb 18,19"] },
      { number: 2, text: "Und <alle,> die israelitischer Abstammung waren, sonderten sich ab* von allen Söhnen der Fremde*. Und sie traten hin und bekannten ihre Sünden und die Verfehlungen ihrer Väter*.", footnotes: ["w. Und der Same Israels sonderte sich ab", "℘ Kap. 10,29; 13,3; Esr 9,1; 10,11", "℘ 3Mo 26,40"] },
      { number: 3, text: "Und sie standen auf an ihrer Stelle, und man las aus dem Buch des Gesetzes des HERRN, ihres Gottes, vor*, ein Viertel des Tages. Und ein <anderes> Viertel <des Tages> bekannten sie <ihre Verfehlungen> und warfen sich nieder vor dem HERRN, ihrem Gott.", footnotes: ["℘ Kap. 8,7.8"] },
      { number: 4, text: "Und Jeschua* und Bani*, Kadmiël, Schebanja, Bunni, Scherebja, Bani, Kenani traten auf das Podium* der Leviten, und sie schrien mit lauter Stimme um Hilfe zu dem HERRN, ihrem Gott*.", footnotes: ["℘ Kap. 3,17; 8,7; 12,8", "℘ 3Mo 23,34.42", "℘ Kap. 8,4", "℘ 2Chr 20,19"] },
      { number: 5, text: "Und die Leviten Jeschua und Kadmiël, Bani, Haschabneja, Scherebja, Hodija, Schebanja, Petachja sagten: Steht auf, preist* den HERRN, euren Gott, von Ewigkeit zu Ewigkeit*! Und man preise* deinen herrlichen Namen*, der erhaben ist über allen Preis und Ruhm*!", footnotes: ["o. segnet", "℘ 1Chr 16,36; 29,20; Dan 2,20", "o. segne", "℘ Hi 1,21; Ps 66,2; 72,19; 99,3", "℘ Ri 13,18; 1Chr 29,11-13"] },
      { number: 6, text: "Du, HERR, bist es, du allein*. Du, du hast den Himmel gemacht, die Himmel der Himmel* und all ihr Heer*, die Erde* und alles, was darauf ist*, die Meere und alles, was in ihnen ist. Und du machst dies alles lebendig*, und das Heer des Himmels wirft sich vor dir nieder*.", footnotes: ["o. Du bist der HERR, du allein\n℘ 5Mo 32,39", "℘ 5Mo 10,14", "℘ 1Mo 2,1", "℘ 1Mo 1,1; Ps 124,8; Jer 32,17", "℘ 1Mo 1,9-25; Apg 4,24", "o. erhältst es alles am Leben\n℘ Kol 1,16.17", "℘ Ps 103,21; Jes 6,2.3"] },
      { number: 7, text: "Du bist es, HERR, Gott, der du Abram erwählt hast* und ihn aus Ur in Chaldäa herausgeführt* und ihm den Namen Abraham verliehen hast*.", footnotes: ["℘ Apg 13,17", "℘ 1Mo 11,31; Jes 41,9; Hebr 11,8", "℘ 1Mo 17,5"] },
      { number: 8, text: "Und du hast sein Herz treu vor dir erfunden und hast mit ihm den Bund geschlossen, das Land der Kanaaniter, der Hetiter, der Amoriter und der Perisiter und der Jebusiter und der Girgasiter zu geben* — es seinen Nachkommen zu geben. Und du hast deine Worte aufrechterhalten*, denn du bist gerecht*.", footnotes: ["℘ 1Mo 15,18-21; Hes 33,24", "℘ Jos 21,43-45", "℘ V. 33; 5Mo 32,4; 2Sam 22,31; Esr 9,15"] },
      { number: 9, text: "Und du hast das Elend unserer Väter in Ägypten angesehen* und hast ihr Geschrei am Schilfmeer gehört*.", footnotes: ["℘ 2Mo 3,7", "℘ 2Mo 14,10.15"] },
      { number: 10, text: "Und du hast Zeichen und Wunder* getan an dem Pharao und an all seinen Knechten und am ganzen Volk seines Landes*. Denn du hattest erkannt, dass sie vermessen an ihnen gehandelt hatten*. Und du hast dir einen Namen gemacht*, wie es am heutigen Tag ist*.", footnotes: ["o. Wahrzeichen", "℘ 2Mo 3,20; 5Mo 7,19", "℘ 2Mo 18,11", "℘ Jes 63,12", "℘ Dan 9,15"] },
      { number: 11, text: "Und das Meer hast du vor ihnen gespalten, so dass sie mitten durch das Meer auf dem Trockenen zogen*. Aber ihre Verfolger hast du in die Tiefen geworfen wie einen Stein in mächtige Wasser*.", footnotes: ["℘ 2Mo 14,14-27; Jer 32,20; Apg 7,36", "℘ 2Mo 14,10.15"] },
      { number: 12, text: "Und in einer Wolkensäule hast du sie bei Tag geleitet und in einer Feuersäule bei Nacht, um ihnen den Weg zu erleuchten, auf dem sie ziehen sollten*.", footnotes: ["℘ 2Mo 13,21; Hes 20,6"] },
      { number: 13, text: "Und auf den Berg Sinai bist du herabgestiegen* und hast vom Himmel her mit ihnen geredet*. Und du hast ihnen klare* Rechtsbestimmungen und zuverlässige Gesetze*, gute Ordnungen und Gebote gegeben*.", footnotes: ["℘ 2Mo 19,18.20; Gal 4,24", "℘ 2Mo 20,22", "w. gerade, o. rechte", "w. Gesetze der Wahrheit, o. Gesetze der Beständigkeit", "℘ 5Mo 4,8; Esr 7,6; Ps 19,8.9"] },
      { number: 14, text: "Und deinen heiligen Sabbat hast du ihnen verkündet* und hast ihnen Gebote und Ordnungen und ein Gesetz geboten durch deinen Knecht Mose*.", footnotes: ["℘ Kap. 10,32; 2Mo 20,8; Hes 20,11", "℘ 2Mo 24,12; Joh 1,17"] },
      { number: 15, text: "Und Brot vom Himmel hast du ihnen gegeben für ihren Hunger* und hast ihnen Wasser aus dem Felsen hervorkommen lassen für ihren Durst*. Und du hast ihnen befohlen* hineinzugehen, um das Land in Besitz zu nehmen, das ihnen zu geben du deine Hand zum Schwur erhoben hattest*.", footnotes: ["℘ 2Mo 16,4.15.35; Joh 6,31", "℘ 2Mo 17,3.6; Jes 48,21", "w. gesagt", "℘ 5Mo 1,8"] },
      { number: 16, text: "Sie aber, unsere Väter nämlich, handelten vermessen, und sie verhärteten ihren Nacken* und hörten nicht auf deine Gebote*.", footnotes: ["℘ 2Mo 32,9; 2Chr 36,13; Jer 7,26", "℘ 2Chr 29,6; Ps 81,12"] },
      { number: 17, text: "Und sie weigerten sich zu gehorchen und dachten nicht <mehr> an deine Wundertaten, die du an ihnen getan hattest*. Sie verhärteten ihren Nacken* und setzten ein Haupt <über sich>, um zu ihrer Knechtschaft in Ägypten zurückzukehren*. Du aber bist ein Gott der Vergebung, gnädig und barmherzig, langsam zum Zorn und groß an Gnade*, und du hast sie nicht verlassen*.", footnotes: ["℘ Ps 78,10.11; Jer 18,15", "℘ 2Mo 32,9; 2Chr 36,13; Jer 7,26", "so mit einigen hebr. Handschr. und LXX; Mas. T.: um in ihrer Widerspenstigkeit zu ihrer Knechtschaft zurückzukehren\n℘ 4Mo 14,4; Dan 9,9", "℘ Ps 86,15", "℘ V. 31; 3Mo 26,44; 1Sam 12,22; Esr 9,9"] },
      { number: 18, text: "Sogar als sie sich ein gegossenes Kalb machten und sagten: Das ist dein Gott, der dich aus Ägypten heraufgeführt hat* — und große Lästerungen verübten,", footnotes: ["℘ 2Mo 32,4.8"] },
      { number: 19, text: "hast du in deinen großen Erbarmungen sie doch nicht in der Wüste verlassen*. Die Wolkensäule wich nicht von ihnen bei Tag, um sie auf dem Weg zu leiten, noch die Feuersäule bei Nacht, um ihnen den Weg zu erleuchten*, auf dem sie ziehen sollten*.", footnotes: ["℘ V. 31; Hes 20,17", "w. um für sie zu leuchten und den Weg", "℘ Ps 136,16"] },
      { number: 20, text: "Und deinen guten Geist hast du gegeben, um sie zu unterweisen*. Und dein Manna hast du ihrem Mund nicht vorenthalten*, und du gabst ihnen Wasser für ihren Durst*.", footnotes: ["℘ 4Mo 11,17.25; Jes 63,11", "℘ 2Mo 17,3.6; Jes 48,21", "℘ 2Mo 17,3.6; Jes 48,21"] },
      { number: 21, text: "Und vierzig Jahre lang hast du sie in der Wüste versorgt, sie entbehrten nichts. Ihre Kleider zerschlissen nicht, und ihre Füße schwollen nicht <an>*.", footnotes: ["℘ 5Mo 2,7; Apg 7,36"] },
      { number: 22, text: "Und du hast ihnen Königreiche und Völker gegeben und sie <ihnen Stück> für Stück zugeteilt*. So nahmen sie das Land Sihons, das Land des Königs von Heschbon, in Besitz und das Land des Og, des Königs von Baschan*.", footnotes: ["℘ Jer 27,5", "℘ 5Mo 4,46.47"] },
      { number: 23, text: "Und ihre Söhne hast du zahlreich werden lassen wie die Sterne des Himmels*. Und du hast sie in das Land gebracht, von dem du ihren Vätern gesagt hattest, dass sie hineingehen sollten*, um es in Besitz zu nehmen*.", footnotes: ["℘ 1Mo 22,17; 2Mo 1,7.12", "o. würden", "℘ Jos 1,2"] },
      { number: 24, text: "Und die Söhne kamen hinein und nahmen das Land in Besitz*. Und du hast vor ihnen die Bewohner des Landes, die Kanaaniter, gedemütigt und hast sie in ihre Hand gegeben, sowohl ihre Könige als auch die Völker des Landes, mit ihnen zu tun nach ihrem Belieben*.", footnotes: ["℘ 4Mo 14,31; Jos 21,43", "℘ Jos 10,40-42; 12; Est 9,5; Apg 7,45"] },
      { number: 25, text: "Und sie nahmen befestigte Städte ein und fettes Ackerland und nahmen Häuser in Besitz*, die mit allerlei Gut gefüllt waren, ausgehauene Zisternen, Weinberge und Olivengärten und Obstbäume in Menge. Und sie aßen und wurden satt* und fett und ließen <es> sich wohl sein durch deine große Güte*.", footnotes: ["℘ Ps 105,44", "℘ 5Mo 6,10.11", "o. in der Fülle deiner Güter\n℘ 5Mo 32,14-16; 1Kö 14,9; Jer 2,7; 32,23"] },
      { number: 26, text: "Aber sie wurden widerspenstig und empörten sich gegen dich und warfen dein Gesetz hinter ihren Rücken*. Und sie brachten deine Propheten um, die als Zeugen gegen sie auftraten*, um sie zu dir zurückzuführen*; und sie verübten große Lästerungen.", footnotes: ["℘ 5Mo 32,14-16; 1Kö 14,9; Jer 2,7; 32,23", "o. sie warnten; o. sie ermahnten", "℘ 1Kö 19,10; Mt 21,35; Apg 7,52"] },
      { number: 27, text: "Da gabst du sie in die Hand ihrer Bedränger*, die bedrängten sie*. Und zur Zeit ihrer Bedrängnis schrien sie zu dir, und du hörtest vom Himmel her, und nach deinen großen Erbarmungen gabst du ihnen Retter; die retteten sie aus der Hand ihrer Bedränger*.", footnotes: ["℘ Ri 2,14-18; 2Kö 17,20", "℘ 3Mo 26,17", "℘ Ps 136,24"] },
      { number: 28, text: "Aber sobald sie Ruhe hatten, taten sie wieder Böses vor dir*. Da überließest du sie der Hand ihrer Feinde, dass diese über sie herrschten, und sie schrien wieder zu dir um Hilfe, und du hörtest vom Himmel her und rettetest sie nach deinen Erbarmungen viele Male*.", footnotes: ["℘ Ri 2,19", "℘ Ps 106,42-45"] },
      { number: 29, text: "Und du tratest als Zeuge gegen sie auf*, um sie zu deinem Gesetz zurückzuführen. Sie aber handelten vermessen und gehorchten deinen Geboten nicht, sondern sündigten gegen deine Rechtsbestimmungen, durch die der Mensch lebt, wenn er sie tut*. Und sie zeigten eine störrische Schulter und verhärteten ihren Nacken und gehorchten nicht*.", footnotes: ["o. warntest sie; o. ermahntest sie", "o. die der Mensch tun soll, damit er durch sie lebt\n℘ 3Mo 18,5; Mt 19,17", "℘ 5Mo 31,27; Ri 6,10"] },
      { number: 30, text: "Und du hattest Geduld mit ihnen* viele Jahre und tratest als Zeuge gegen sie auf* durch deinen Geist, durch das Wort* deiner Propheten*, aber sie hörten nicht hin*. Da gabst du sie in die Hand der Völker der Länder*.", footnotes: ["w. du bewahrtest <Gnade> über ihnen, o. du zogst es hin mit ihnen", "o. warntest sie; o. ermahntest sie", "w. durch die Hand", "℘ 2Chr 24,19", "℘ Esr 9,10; Jer 44,4.5; Dan 9,6", "℘ 2Kö 18,11.12"] },
      { number: 31, text: "Doch in deinen großen Erbarmungen hast du nicht ein Ende mit ihnen gemacht und sie nicht verlassen. Denn ein gnädiger und barmherziger Gott bist du!*", footnotes: ["℘ 5Mo 4,31; 2Chr 30,9; Kla 3,22"] },
      { number: 32, text: "Und nun, unser Gott, du großer, starker und furchtbarer Gott*, der den Bund und die Gnade bewahrt*, lass nicht gering vor dir sein all die Mühsal, die uns getroffen hat, unsere Könige, unsere Obersten und unsere Priester und unsere Propheten und unsere Väter und dein ganzes Volk, seit den Tagen der Könige von Assur bis auf diesen Tag!*", footnotes: ["℘ Kap. 1,5", "℘ 5Mo 7,12", "℘ 2Kö 17,6.23"] },
      { number: 33, text: "Doch du bist gerecht bei allem*, was über uns gekommen ist, denn du hast Treue bewiesen*; wir aber, wir haben gottlos gehandelt*.", footnotes: ["℘ V. 8; Ps 119,137; Kla 1,18", "o. du hast Wahrheit getan", "o. wir aber, wir haben uns schuldig gemacht\n℘ 2Mo 32,31; 3Mo 26,41; Ps 106,6; Hes 11,12"] },
      { number: 34, text: "Und unsere Könige, unsere Obersten, unsere Priester und unsere Väter haben nicht nach deinem Gesetz gehandelt* und haben auf deine Gebote und auf deine Zeugnisse nicht geachtet*, mit denen du gegen sie als Zeuge aufgetreten bist*.", footnotes: ["℘ Esr 9,10; Jer 44,4.5; Dan 9,6", "℘ Esr 9,10; Jer 44,4.5; Dan 9,6", "o. mit denen du sie gewarnt hast o. ermahnt hast"] },
      { number: 35, text: "Sie aber — trotz ihres Königreiches* und trotz der Fülle deiner Güter, die du ihnen gegeben, und trotz des weiten und fetten Landes, das du vor sie gelegt hattest* —, sie haben dir nicht gedient und sind nicht umgekehrt von ihren bösen Taten*.", footnotes: ["d. h. obwohl ihnen ein eigenes Königreich verliehen war", "℘ 5Mo 28,47.48", "℘ Hes 5,6"] },
      { number: 36, text: "Siehe, wir sind heute Knechte. Und das Land, das du unseren Vätern gegeben hast, seine Früchte und seine Güter zu genießen — siehe, wir sind Knechte in ihm*!", footnotes: ["℘ Esr 9,9; Kla 5,4; Joh 8,33"] },
      { number: 37, text: "Und seinen Ertrag vermehrt es für die Könige, die du um unserer Sünden willen über uns gesetzt hast. Und sie haben Gewalt über unsere Leiber und über unser Vieh nach ihrem Belieben*; wir aber sind in großer Bedrängnis.", footnotes: ["℘ 5Mo 28,33"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und wegen all dessen schließen wir <nun> eine <feste> Vereinbarung* und schreiben <sie> auf. Und auf der gesiegelten <Schrift>* <stehen die Namen> unserer Obersten, unserer Leviten <und> unserer Priester.", heading: "Verpflichtung auf das Gesetz und zu Abgaben an das Haus Gottes", footnotes: ["℘ V. 30; Esr 10,3", "℘ 2Mo 24,4"] },
      { number: 2, text: "Und <die Namen> auf den gesiegelten <Schriftstücken>: Nehemia, der Tirschata*, der Sohn Hachaljas, und Zedekia.", footnotes: ["d. i. der Statthaltertitel Nehemias\n℘ Esr 2,63"] },
      { number: 3, text: "*Seraja*, Asarja*, Jirmeja*,", footnotes: ["℘ V. 3-9: Kap. 12,2-7", "℘ Kap. 11,11", "℘ Kap. 12,33.34", "℘ Esr 9,10; Jer 44,4.5; Dan 9,6"] },
      { number: 4, text: "Paschhur, Amarja, Malkija," },
      { number: 5, text: "Hattusch*, Schebanja, Malluch,", footnotes: ["℘ Kap. 3,10"] },
      { number: 6, text: "Harim, Meremot, Obadja," },
      { number: 7, text: "Daniel, Ginneton, Baruch," },
      { number: 8, text: "Meschullam, Abija, Mijamin," },
      { number: 9, text: "Maasja, Bilga, Schemaja*; das sind die Priester. —", footnotes: ["℘ Kap. 12,34"] },
      { number: 10, text: "Und die Leviten: Jeschua, der Sohn Asanjas, Binnui*, von den Söhnen Henadads*, Kadmiël*;", footnotes: ["℘ Esr 8,33", "℘ Kap. 3,24", "℘ Kap. 7,43; 12,8"] },
      { number: 11, text: "und ihre Brüder: Schechanja*, Hodija, Kelita, Pelaja, Hanan,", footnotes: ["so mit einigen hebr. Handschr., LXX und der syr. Üs.; Mas. T.: Schebanja"] },
      { number: 12, text: "Micha, Rehob, Haschabja," },
      { number: 13, text: "Sakkur, Scherebja, Schebanja," },
      { number: 14, text: "Hodija, Bani, Beninu." },
      { number: 15, text: "*Die Häupter des Volkes: Parosch, Pahat-Moab, Elam, Sattu, Bani,", footnotes: ["℘ V. 15-20: Esr 2,3-19"] },
      { number: 16, text: "Bunni, Asgad, Bebai," },
      { number: 17, text: "Adonija, Bigwai, Adin," },
      { number: 18, text: "Ater, Hiskia, Asur," },
      { number: 19, text: "Hodija, Haschum, Bezai," },
      { number: 20, text: "Harif, Anatot, Nebai," },
      { number: 21, text: "Magpiasch, Meschullam, Hesir," },
      { number: 22, text: "Meschesabel, Zadok, Jaddua," },
      { number: 23, text: "Pelatja, Hanan, Anaja," },
      { number: 24, text: "Hoschea, Hananja, Haschub," },
      { number: 25, text: "Lohesch, Pilha, Schobek," },
      { number: 26, text: "Rehum, Haschabna, Maaseja," },
      { number: 27, text: "und Ahija, Hanan, Anan," },
      { number: 28, text: "Malluch, Harim, Baana." },
      { number: 29, text: "Und das übrige Volk, die Priester, die Leviten, die Torhüter, die Sänger, die Tempeldiener* und alle, die sich aus den Völkern der Länder zum Gesetz Gottes hin abgesondert haben*, <sowie> ihre Frauen, ihre Söhne und ihre Töchter, alle, die Erkenntnis <und> Einsicht haben*,", footnotes: ["℘ Kap. 7,46-56.60", "℘ Kap. 9,2; 3Mo 20,26", "℘ Kap. 8,2"] },
      { number: 30, text: "schließen sich ihren Brüdern, den Mächtigen unter ihnen, an und treten in Eid* und Schwur, im Gesetz Gottes zu leben*, das durch Mose, den Knecht Gottes, gegeben worden ist, und alle Gebote des HERRN, unseres Herrn, und seine Rechtsbestimmungen und seine Ordnungen zu bewahren und zu tun*.", footnotes: ["℘ V. 1; Kap. 5,12; 5Mo 29,11", "w. zu gehen", "℘ 2Kö 23,3.25; 2Chr 34,31; Ps 119,106"] },
      { number: 31, text: "<Und sie schwören:> Wir wollen unsere Töchter nicht den Völkern des Landes geben, und ihre Töchter nicht für unsere Söhne nehmen*.", footnotes: ["℘ Kap. 13,23-27; 2Mo 34,16"] },
      { number: 32, text: "Wenn die Völker des Landes am Sabbattag ihre* Waren und allerlei Getreide zum Verkauf bringen, wollen wir es ihnen am Sabbat oder an einem <andern> heiligen Tag nicht abnehmen*. Wir wollen im siebten Jahr auf den Ernteertrag und auf die Schuldforderung einer jeden Hand verzichten*.", footnotes: ["w. die", "℘ Kap. 9,14; 13,15-22", "w. Wir wollen brach liegen lassen das siebte Jahr und die Schuldforderung einer jeden Hand\n℘ Kap. 5,10; 2Mo 23,11"] },
      { number: 33, text: "Wir wollen uns als Gebot auferlegen, ein Drittel Schekel im Jahr für den Dienst im Haus unseres Gottes zu geben*:", footnotes: ["℘ 2Mo 30,16; Mt 17,24"] },
      { number: 34, text: "für die Schaubrote* und das regelmäßige Speisopfer und für das ständige Brandopfer* <und für die Opfer an> den Sabbaten* <und> Neumonden*, für die Festzeiten* und für die heiligen Dinge und für die Sündopfer, um Sühnung zu erwirken für Israel und für alles Werk im Haus unseres Gottes.", footnotes: ["w. für das aufgeschichtete Brot\n℘ 3Mo 24,5-7", "℘ 4Mo 28,2.3", "℘ 2Chr 2,3; Esr 3,5", "℘ Esr 9,10; Jer 44,4.5; Dan 9,6", "℘ Esr 9,10; Jer 44,4.5; Dan 9,6"] },
      { number: 35, text: "Wir, die Priester, die Leviten und das Volk, wollen die Lose werfen über die Lieferung des Brennholzes*, um es nach unseren Familien* zu bestimmten Zeiten zum Haus unseres Gottes zu bringen, Jahr für Jahr, damit man es auf dem Altar des HERRN, unseres Gottes, verbrennt, wie es im Gesetz geschrieben steht*.", footnotes: ["℘ Kap. 13,31", "w. um es entsprechend dem Haus unserer Väter", "℘ 3Mo 6,5.6"] },
      { number: 36, text: "<Wir verpflichten uns,> die Erstlinge unseres Ackerlandes und die Erstlinge aller Früchte von allen Bäumen Jahr für Jahr zum Haus des HERRN zu bringen*.", footnotes: ["℘ Kap. 12,44; 13,5; 2Mo 23,19; 2Chr 31,5; Mal 3,10"] },
      { number: 37, text: "<Wir verpflichten uns,> die Erstgeborenen unserer Söhne und unseres Viehbestandes, wie es im Gesetz vorgeschrieben ist, und zwar die Erstgeborenen unserer Rinder und unserer Schafe zum Haus unseres Gottes zu bringen, für die Priester, die im Haus unseres Gottes Dienst verrichten*.", footnotes: ["℘ 2Mo 13,2; 4Mo 18,15-18"] },
      { number: 38, text: "Wir wollen das Erste* von unserm Schrotmehl* und unseren Hebopfern und den Früchten von allerlei Bäumen, <von> Most und Öl für die Priester bringen, in die Zellen des Hauses unseres Gottes*, und den Zehnten unseres Ackerlandes für die Leviten*. Denn sie, die Leviten, sind es, die den Zehnten erheben sollen in allen Städten unseres Ackerbaus*.", footnotes: ["d. i. das Beste", "o. unseres Teiges", "℘ Kap. 13,31; 4Mo 15,19-21", "℘ 4Mo 18,21", "d. h. in den Städten im Einzugsbereich des Tempels\n℘ 3Mo 27,30; 5Mo 14,22"] },
      { number: 39, text: "Und der Priester, der Sohn Aarons, soll bei den Leviten sein, wenn die Leviten den Zehnten erheben. Und die Leviten sollen den Zehnten vom Zehnten zum Haus unseres Gottes hinaufbringen*, in die Zellen des Schatzhauses*.", footnotes: ["℘ 4Mo 18,26-29", "℘ Kap. 12,47; 13,12; 2Chr 31,11.12"] },
      { number: 40, text: "Denn in die Zellen sollen die Söhne Israel und die Söhne Levi das Hebopfer vom Getreide, vom Most und Öl bringen*. Denn dort sind die heiligen Geräte* und die Priester, die den Dienst verrichten, und die Torhüter und die Sänger*. So wollen wir das Haus unseres Gottes nicht <im Stich> lassen*.", footnotes: ["℘ Kap. 12,47; 13,12; 2Chr 31,11.12", "℘ Esr 8,28", "℘ Kap. 7,39-45", "℘ Kap. 13,10"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und die Obersten des Volkes wohnten in Jerusalem*. Und das übrige Volk warf Lose*, um je einen von zehn kommen zu lassen, damit er in Jerusalem, der heiligen Stadt*, wohne*, die neun <anderen> Teile aber in den Städten blieben.", heading: "Verzeichnis der Bewohner Jerusalems und Judas", footnotes: ["℘ V. 1-9: 1Chr 9,2-9", "℘ 1Chr 8,28", "℘ Jos 18,10", "℘ Jes 52,1; Mt 4,5; Offb 11,2; 21,2", "℘ Kap. 7,4; Ps 122,6"] },
      { number: 2, text: "Und das Volk segnete alle Männer, die sich bereit zeigten, in Jerusalem zu wohnen*.", footnotes: ["℘ Kap. 7,4; Ps 122,6"] },
      { number: 3, text: "Und dies sind die Oberhäupter der Provinz <Juda>, die in Jerusalem wohnten — in den Städten Judas aber wohnten, jeder auf seinem Besitz in ihren Städten: Israel, die Priester, die Leviten, die Tempeldiener und die Söhne der Knechte Salomos* —;", footnotes: ["℘ Kap. 7,7-60"] },
      { number: 4, text: "und zwar wohnten in Jerusalem einige von den Söhnen Juda und von den Söhnen Benjamin: Von den Söhnen Juda: Ataja, der Sohn Usijas, des Sohnes Secharjas, des Sohnes Amarjas, des Sohnes Schefatjas, des Sohnes Mahalalels, von den Söhnen Perez;" },
      { number: 5, text: "und Maaseja, der Sohn Baruchs, des Sohnes Kolhoses, des Sohnes Hasajas, des Sohnes Adajas, des Sohnes Jojaribs, des Sohnes Secharjas, von den Schilonitern*.", footnotes: ["Andere lesen mit 4Mo 26,20: von den Schelanitern"] },
      { number: 6, text: "Alle Söhne des Perez, die in Jerusalem wohnten, waren 468 tapfere* Männer.", footnotes: ["o. vermögende; o. angesehene"] },
      { number: 7, text: "Und dies sind die Söhne Benjamin: Sallu, der Sohn Meschullams, des Sohnes Joëds, des Sohnes Pedajas, des Sohnes Kolajas, des Sohnes Maasejas, des Sohnes Itiëls, des Sohnes Jesajas," },
      { number: 8, text: "und seine Brüder* Gabbai, Sallai, 928.", footnotes: ["so mit einer Ausgabe der LXX; Mas. T.: und nach ihm"] },
      { number: 9, text: "Und Joel, der Sohn Sichris, war Aufseher über sie; und Juda, der Sohn Senuas, war als Zweiter über die Stadt <gesetzt>." },
      { number: 10, text: "*Von den Priestern: Jedaja, Jojarib*, Jachin <und>", footnotes: ["℘ V. 10-14: 1Chr 9,10-13", "so mit einer hebr. Handschr. und 1Chr 9,10; Mas. T.: der Sohn Jojaribs"] },
      { number: 11, text: "Seraja*, der Sohn Hilkijas, des Sohnes Meschullams, des Sohnes Zadoks, des Sohnes Merajots, des Sohnes Ahitubs, Fürst des Gotteshauses*,", footnotes: ["℘ Kap. 10,3", "℘ 2Chr 31,13"] },
      { number: 12, text: "und ihre Brüder, die den <Opfer>dienst im Haus verrichteten: 822; und Adaja, der Sohn Jerohams, des Sohnes Pelaljas, des Sohnes Amzis, des Sohnes Secharjas, des Sohnes Paschhurs, des Sohnes Malkijas," },
      { number: 13, text: "und seine Brüder, <alles> Familienoberhäupter*: 242; und Amaschsai, der Sohn Asarels, des Sohnes Achsais, des Sohnes Meschillemots, des Sohnes Immers,", footnotes: ["w. Häupter der Väter"] },
      { number: 14, text: "und ihre Brüder, angesehene* Männer: 128. Und Aufseher über sie war Sabdiël, der Sohn Haggadolims.", footnotes: ["o. vermögende"] },
      { number: 15, text: "*Und von den Leviten: Schemaja, der Sohn Haschubs, des Sohnes Asrikams, des Sohnes Haschabjas, des Sohnes Bunnis;", footnotes: ["℘ V. 15-23: 1Chr 9,14-34"] },
      { number: 16, text: "und Schabbetai und Josabad, von den Häuptern der Leviten, <die> über den äußeren Dienst am Haus Gottes <zu wachen hatten>;" },
      { number: 17, text: "und Mattanja, der Sohn Michas, des Sohnes Sabdis, des Sohnes Asafs, der Leiter des Lobsingens*, er stimmte beim Gebet den Lobpreis an*, und Bakbukja, sein Stellvertreter* unter seinen Brüdern; und Abda, der Sohn Schammuas, des Sohnes Galals, des Sohnes Jedutuns*.", footnotes: ["so mit einer LXX-Ausgabe und Vulg.; Mas. T.: der Leiter beim Anfang", "℘ Kap. 12,8.24.46", "w. der Zweite", "℘ 1Chr 25,1-6"] },
      { number: 18, text: "Alle Leviten in der heiligen Stadt waren 284." },
      { number: 19, text: "Und die Torhüter: Akkub, Talmon und ihre Brüder*, die in den Toren Wache hielten, 172. —", footnotes: ["℘ Kap. 12,25"] },
      { number: 20, text: "Und das übrige Israel, die Priester, die Leviten, <blieben> in allen Städten Judas, jeder in seinem Erbteil*.", footnotes: ["℘ Jos 24,28"] },
      { number: 21, text: "Und die Tempeldiener wohnten auf dem Ofel*; und Ziha* und Gischpa waren über die Tempeldiener <gesetzt>. —", footnotes: ["w. Buckel; d. i. ein Hügel südlich des Tempelberges\n℘ Kap. 3,26", "℘ Esr 2,43"] },
      { number: 22, text: "Und Aufseher der Leviten in Jerusalem war Usi, der Sohn Banis, des Sohnes Haschabjas, des Sohnes Mattanjas, des Sohnes Michas, von den Söhnen Asafs, die beim <Gottes>dienst im Haus Gottes sangen." },
      { number: 23, text: "Denn <es gab> ein Gebot des Königs über sie und eine Vorschrift für die Sänger, wer täglich zu singen hatte*.", footnotes: ["w. für die Sänger <in Bezug auf> die Sache des Tages an ihrem Tag\n℘ Esr 6,8-10"] },
      { number: 24, text: "Und Petachja, der Sohn Meschesabels, von den Söhnen Serachs, des Sohnes Judas*, <stand> dem König zur Seite für alle Angelegenheiten des Volkes.", footnotes: ["℘ 1Mo 46,12"] },
      { number: 25, text: "*Und in den Gehöften auf ihren Feldern wohnten von den Söhnen Juda <einige> in Kirjat-Arba* und seinen Tochterstädten und in Dimona und seinen Tochterstädten und in Kabzeel und seinen Gehöften", footnotes: ["℘ V. 25-30: Jos 15,21-62", "℘ Jos 14,15"] },
      { number: 26, text: "und in Jeschua und in Molada* und in Bet-Pelet", footnotes: ["℘ 1Chr 4,28"] },
      { number: 27, text: "und in Hazar-Schual und in Beerscheba* und seinen Tochterstädten", footnotes: ["℘ 1Chr 4,28"] },
      { number: 28, text: "und in Ziklag* und in Mechona und in seinen Tochterstädten", footnotes: ["℘ 1Chr 4,30"] },
      { number: 29, text: "und in En-Rimmon und in Zora und in Jarmut," },
      { number: 30, text: "Sanoach*, Adullam und seinen Gehöften, Lachisch und seinen Feldern, Aseka und seinen Tochterstädten. So ließen sie sich nieder von Beerscheba bis zum Tal Hinnom*.", footnotes: ["℘ Kap. 3,13", "℘ Jos 15,8"] },
      { number: 31, text: "Und die Söhne Benjamin <wohnten> von Geba an in Michmas* und Aja und Bethel* und seinen Tochterstädten,", footnotes: ["℘ 1Sam 13,2", "℘ Kap. 7,30-32; Jos 18,22"] },
      { number: 32, text: "in Anatot*, Nob*, Ananja,", footnotes: ["℘ Jos 21,18; Jes 10,30", "℘ 1Sam 21,1"] },
      { number: 33, text: "Hazor*, Rama*, Gittajim*,", footnotes: ["℘ 2Sam 13,23", "℘ Jos 18,25", "℘ 2Sam 4,3"] },
      { number: 34, text: "Hadid, Zeboïm*, Neballat,", footnotes: ["℘ 1Sam 13,18"] },
      { number: 35, text: "Lod und Ono* <und> im Tal der Handwerker*.", footnotes: ["℘ Kap. 6,2", "℘ 1Chr 4,14"] },
      { number: 36, text: "Und von den Leviten <wohnten> Abteilungen in Juda und in Benjamin*.", footnotes: ["so mit mehreren LXX-Handschr.; Mas. T.: Und von den Leviten gehörten Abteilungen Judas zu Benjamin"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Und dies sind die Priester und die Leviten, die mit Serubbabel, dem Sohn Schealtiëls, und Jeschua* hinaufgezogen waren*: Seraja, Jirmeja, Esra,", heading: "Verzeichnis der Priester und Leviten", footnotes: ["℘ V. 2-7: Kap. 10,3-9", "℘ Hag 1,1", "℘ Esr 2,1"] },
      { number: 2, text: "Amarja, Malluch, Hattusch," },
      { number: 3, text: "Schechanja, Rehum*, Meremot,", footnotes: ["d. i. Harim; vgl. V. 15\n℘ Kap. 3,17"] },
      { number: 4, text: "Iddo, Ginneton, Abija," },
      { number: 5, text: "Mijamin, Maadja, Bilga," },
      { number: 6, text: "Schemaja und Jojarib, Jedaja," },
      { number: 7, text: "Sallu, Amok, Hilkija, Jedaja. Das waren die Häupter der Priester und ihrer Brüder in den Tagen Jeschuas. —" },
      { number: 8, text: "Und die Leviten: Jeschua*, Binnui, Kadmiël*, Scherebja*, Juda, Mattanja. Er und seine Brüder waren über die Lobpreisungen <als Leiter gesetzt>*,", footnotes: ["℘ Kap. 7,43; Esr 2,40", "℘ 1Chr 4,28", "℘ V. 24; Kap. 9,4.5", "℘ Kap. 11,17"] },
      { number: 9, text: "während Bakbukja und Unni und ihre Brüder* ihnen nach Dienstabteilungen gegenüberstanden.", footnotes: ["so mit einigen hebr. Handschr., einer LXX-Ausgabe und Vulg.; Mas. T.: Bakbukja und Unni, ihre Brüder"] },
      { number: 10, text: "Und Jeschua zeugte Jojakim, und Jojakim zeugte Eljaschib*, und Eljaschib zeugte Jojada*,", footnotes: ["℘ Kap. 3,1", "℘ Kap. 13,28"] },
      { number: 11, text: "und Jojada zeugte Johanan, und Johanan* zeugte Jaddua*.", footnotes: ["so mit V. 22 und 23; Mas. T.: Jonatan, und Jonatan", "℘ V. 22"] },
      { number: 12, text: "*Und in den Tagen Jojakims waren <folgende> Priester Familienoberhäupter*: von <der Familie> Seraja: Meraja; von Jirmeja: Hananja;", footnotes: ["℘ V. 12-21: vgl. 1Chr 24,4-19", "o. waren <folgende> Familienoberhäupter Priester; w. waren Priester, Häupter"] },
      { number: 13, text: "von Esra: Meschullam; von Amarja: Johanan;" },
      { number: 14, text: "von Malluch*: Jonatan; von Schebanja: Josef;", footnotes: ["so mit LXX; Mas. T. schwankt zwischen Melichu und Maluchi"] },
      { number: 15, text: "von Harim: Adna; von Merajot: Helkai;" },
      { number: 16, text: "von Iddo: Secharja*; von Ginneton: Meschullam;", footnotes: ["℘ Sach 1,1"] },
      { number: 17, text: "von Abija: Sichri; von Mijamin . . .; von Maadja*: Piltai;", footnotes: ["so mit V. 5; Mas. T.: Moadja"] },
      { number: 18, text: "von Bilga: Schammua; von Schemaja: Jonatan;" },
      { number: 19, text: "und von Jojarib: Mattenai; von Jedaja: Usi;" },
      { number: 20, text: "von Sallai*: Kallai; von Amok: Eber;", footnotes: ["LXX: Sallu"] },
      { number: 21, text: "von Hilkija: Haschabja; von Jedaja: Netanel. —" },
      { number: 22, text: "In den Tagen Eljaschibs, Jojadas und Johanans und Jadduas* wurden die Leviten nach <ihren> Familienoberhäuptern* sowie die Priester <in dem Buch der Geschichte> bis zu der Regierung des Persers Darius* aufgeschrieben.", footnotes: ["℘ V. 10.11", "w. Häuptern der Väter", "d. i. Darius II. <423—404 v. Chr.>, der Nachfolger Artaxerxes' I."] },
      { number: 23, text: "Die Söhne Levis, die Familienoberhäupter, sind im Buch der Geschichte* aufgeschrieben, und zwar bis zu den Tagen Johanans, des Sohnes Eljaschibs. —", footnotes: ["w. im Buch der Begebenheiten der Tage"] },
      { number: 24, text: "Und die Häupter der Leviten waren Haschabja, Scherebja und Jeschua, Binnui, Kadmiël* und ihre Brüder, <die> ihnen gegenüber<standen>, um zu loben <und> zu preisen nach dem Gebot Davids, des Mannes Gottes, Dienstabteilung neben Dienstabteilung*,", footnotes: ["so mit V. 8 und Kap. 9,4; 10,10; Mas. T.: Jeschua, der Sohn des Kadmiël", "℘ V. 8.36; Kap. 11,17; 1Chr 16,4.5; 25,6"] },
      { number: 25, text: "<nämlich> Mattanja und Bakbukja, Obadja. Meschullam <aber>, Talmon <und> Akkub hielten als Torhüter Wache* bei den Vorratskammern der Tore*. —", footnotes: ["so mit anderer Zeichensetzung in Anlehnung an Kap. 11,17; Mas. T.: Mattanja und Bakbukja, Obadja, Meschullam, Talmon und Akkub hielten als Torhüter Wache", "℘ Kap. 11,19; 1Chr 26,15.17; 2Chr 8,14"] },
      { number: 26, text: "Diese <lebten> in den Tagen Jojakims, des Sohnes Jeschuas, des Sohnes Jozadaks, und in den Tagen des Statthalters Nehemia und des Priesters Esra, des Schriftgelehrten*.", footnotes: ["℘ Kap. 8,1"] },
      { number: 27, text: "Und bei der Einweihung der Mauer von Jerusalem holte* man die Leviten aus allen ihren Orten, um sie nach Jerusalem zu bringen, damit man die Einweihung mit Freuden feiern könnte* und mit Lobliedern und mit Gesang, <mit> Zimbeln, Harfen und Zithern*.", heading: "Einweihung der Mauer — Tempelabgaben — Aussonderung der Fremden", footnotes: ["w. suchte, o. forschte", "℘ Esr 6,16", "℘ 1Chr 15,16; 2Chr 5,13; 29,25"] },
      { number: 28, text: "Da versammelten sich die Söhne der Sänger sowohl aus dem Kreis* <und> der Umgebung von Jerusalem als auch aus den Gehöften der Netofatiter*", footnotes: ["℘ Kap. 3,22", "℘ Kap. 7,26; 1Chr 9,16"] },
      { number: 29, text: "sowie aus Bet-Gilgal und aus dem Gebiet* von Geba* und Asmawet*; denn die Sänger hatten sich in der Umgebung von Jerusalem Gehöfte gebaut*.", footnotes: ["w. von den Feldern", "℘ Kap. 7,30", "℘ Kap. 7,28; Esr 2,24", "℘ Kap. 13,10"] },
      { number: 30, text: "Und die Priester und die Leviten reinigten sich*; und sie reinigten das Volk und die Tore und die Mauer*.", footnotes: ["℘ Kap. 13,22; 1Chr 15,14", "℘ 2Chr 29,5"] },
      { number: 31, text: "Und ich ließ die Obersten von Juda oben auf die Mauer steigen. Und ich stellte zwei große Dankchöre und Festzüge auf. <Der eine zog> nach rechts*, oben auf der Mauer zum Aschentor* hin.", footnotes: ["d. h. südlich", "o. zum Misttor\n℘ Kap. 2,13"] },
      { number: 32, text: "Und hinter ihnen* her gingen Hoschaja und die Hälfte der Obersten von Juda", footnotes: ["d. h. dem ersten Chor"] },
      { number: 33, text: "und Asarja*, Esra und Meschullam,", footnotes: ["℘ Kap. 10,3"] },
      { number: 34, text: "Juda und Benjamin und Schemaja* und Jirmeja*,", footnotes: ["℘ Kap. 10,9", "℘ Kap. 10,3"] },
      { number: 35, text: "sodann <einige> von den Söhnen der Priester mit Trompeten: Secharja, der Sohn Jonatans, des Sohnes Schemajas, des Sohnes Mattanjas, des Sohnes Michajas, des Sohnes Sakkurs, des Sohnes Asafs," },
      { number: 36, text: "und seine Brüder, Schemaja und Asarel, Milalai, Gilalai, Maai, Netanel und Juda, Hanani mit den Musikinstrumenten Davids, des Mannes Gottes*. Esra aber, der Schriftgelehrte, <ging> vor ihnen her.", footnotes: ["℘ V. 24; 2Chr 8,14"] },
      { number: 37, text: "Und <sie zogen> zum Quelltor* hin und stiegen geradeaus auf den Stufen zur Stadt Davids <und> auf dem Aufgang zur <inneren> Mauer hinauf <und> oberhalb vom Haus Davids entlang und bis an das Wassertor* im Osten.", footnotes: ["℘ Kap. 2,14", "℘ Kap. 3,26"] },
      { number: 38, text: "Und der zweite Dankchor zog zur entgegengesetzten Seite und ich hinter ihm her mit der <anderen> Hälfte <der Oberen> des Volkes oben auf der Mauer über den Ofenturm* und bis an die breite Mauer*,", footnotes: ["℘ Kap. 3,11", "℘ Kap. 3,8"] },
      { number: 39, text: "über das Ephraim-Tor* und über das Jeschana-Tor*, über das Fischtor* und den Turm Hananel* und den Turm Mea bis an das Schaftor; und sie blieben beim Wachttor* stehen.", footnotes: ["℘ Kap. 8,16", "d. i. das »Alte Tor«, o. das Tor der Altstadt\n℘ Kap. 3,6", "℘ Kap. 3,3", "℘ Kap. 3,1", "℘ Kap. 3,25"] },
      { number: 40, text: "Und die beiden Dankchöre stellten sich am Haus Gottes auf, ebenso ich und die Hälfte der Vorsteher mit mir" },
      { number: 41, text: "und die Priester Eljakim, Maaseja, Mijamin, Michaja, Eljoënai, Secharja, Hananja mit Trompeten" },
      { number: 42, text: "und Maaseja und Schemaja und Eleasar und Usi und Johanan und Malkija und Elam und Eser. Dann ließen sich die Sänger unter der Leitung von Jisrachja hören*.", footnotes: ["w. Und die Sänger ließen sich hören, und Jisrachja war ihr Aufseher\n℘ Ps 81,2.3"] },
      { number: 43, text: "Und sie schlachteten an diesem Tag große Schlachtopfer* und freuten sich, denn Gott hatte sie mit großer Freude erfüllt*; und auch die Frauen und die Kinder freuten sich. Und die Freude Jerusalems war weithin zu hören*.", footnotes: ["℘ Kap. 3,34", "℘ V. 27; 2Chr 20,27", "℘ Esr 3,13"] },
      { number: 44, text: "Und es wurden an diesem Tag* Männer eingesetzt* <zur Aufsicht> über die Kammern für die Vorräte, die Hebopfer, die Erstlinge und die Zehnten, um in ihnen die gesetzlichen Anteile für die Priester und für die Leviten von den Feldern* zu sammeln*. Denn Juda hatte seine Freude an den Priestern und an den Leviten, die <im heiligen Dienst> standen.", footnotes: ["d. h. zu jener Zeit", "℘ Kap. 10,36; 13,13; 1Chr 26,20", "w. nach den Feldern; d. h. entsprechend der Größe der Felder", "℘ Kap. 10,36"] },
      { number: 45, text: "Und sie versahen den Dienst ihres Gottes und den Dienst der Reinigung*. Auch die Sänger und die Torhüter <taten Dienst> nach dem Gebot Davids <und> seines Sohnes Salomo*.", footnotes: ["d. h. sie stellten die Reinheit der Opfernden nach dem Opfer fest", "℘ 1Chr 25; 26"] },
      { number: 46, text: "Denn seit* den Tagen Davids und Asafs, seit alter Zeit, gab es Häupter der Sänger und Preis- und Lobgesang für Gott*.", footnotes: ["o. in", "℘ Kap. 11,17; 1Chr 25,6"] },
      { number: 47, text: "Und ganz Israel gab in den Tagen Serubbabels* und in den Tagen Nehemias die Anteile für die Sänger und die Torhüter, was ihnen Tag für Tag zukam*; die Weihegaben aber gaben sie den Leviten, und die Leviten gaben die Weihegaben den Söhnen Aarons*.", footnotes: ["℘ Esr 2,2", "w. die Sache des Tages an ihrem Tag", "w. Und sie weihten <Gaben> den Leviten, und die Leviten weihten <Gaben> den Söhnen Aarons\n℘ Kap. 10,39; 5Mo 18,8"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "An jenem Tag* wurde aus dem Buch des Mose vor den Ohren des Volkes vorgelesen*, und man fand darin geschrieben, dass kein Ammoniter und Moabiter in die Versammlung Gottes kommen sollte für ewig.", footnotes: ["d. h. zu jener Zeit", "℘ Kap. 8,2.3.8"] },
      { number: 2, text: "Denn sie waren den Söhnen Israel nicht mit Brot und mit Wasser entgegengekommen und hatten Bileam gegen sie angeheuert, sie zu verfluchen*, aber unser Gott hatte den Fluch in Segen verwandelt*.", footnotes: ["℘ 4Mo 22,5.6", "℘ 4Mo 24,10"] },
      { number: 3, text: "Und es geschah, als sie das Gesetz hörten, da sonderten sie alles Mischvolk von Israel ab*.", footnotes: ["℘ Kap. 9,2; 2Mo 12,38"] },
      { number: 4, text: "Vordem aber hatte der Priester Eljaschib*, der über die Zellen* des Hauses unseres Gottes gesetzt war, ein Verwandter des Tobija*,", heading: "Zweiter Aufenthalt Nehemias in Jerusalem — Tempelreinigung — Versorgung der Leviten — Sabbatheiligung — Strafrede wegen der Mischehen", footnotes: ["℘ Kap. 3,1", "T.; Mas. T.: über eine Zelle", "℘ V. 28; Kap. 2,10.19"] },
      { number: 5, text: "diesem eine große Zelle hergerichtet. Vordem hatte man dort die Speisopfer gelagert, den Weihrauch und die Geräte und den Zehnten vom Getreide, Most und Öl, <also> die Anteile* für die Leviten und die Sänger und die Torhüter, und die Hebopfer der Priester*.", footnotes: ["so mit Vulg.; Mas. T.: das Gebotene", "℘ Kap. 10,36; 2Chr 31,11"] },
      { number: 6, text: "Bei alldem war ich aber nicht in Jerusalem gewesen, denn im 32. Jahr Artahsastas*, des Königs von Babel, war ich zum König gekommen und hatte mir <erst> nach Verlauf einer <längeren> Zeit vom König <Urlaub> erbeten*.", footnotes: ["℘ Kap. 5,14", "℘ Kap. 2,6"] },
      { number: 7, text: "Als ich nun nach Jerusalem kam, bemerkte ich das Unrecht, das Eljaschib zugunsten von Tobija getan hatte, als er ihm eine Zelle in den Höfen des Hauses Gottes hergerichtet hatte." },
      { number: 8, text: "Das missfiel mir sehr*, und ich warf alle Hausgeräte Tobijas aus der Zelle hinaus*.", footnotes: ["℘ Kap. 5,6", "℘ Mt 21,12"] },
      { number: 9, text: "Dann befahl ich, dass man die Zellen reinigen sollte*, und brachte die Geräte des Hauses Gottes, das Speisopfer und den Weihrauch wieder hinein.", footnotes: ["℘ 2Chr 29,15.16"] },
      { number: 10, text: "Und ich erkannte, dass die Anteile für die Leviten nicht gegeben worden waren*, so dass die Leviten und die Sänger, die den Dienst taten, davongelaufen waren*, jeder auf sein Feld*.", footnotes: ["℘ Jes 43,23; Mal 3,8-10", "℘ Kap. 10,40", "℘ Kap. 12,28.29; 4Mo 35,2"] },
      { number: 11, text: "Da zog ich die Vorsteher zur Rechenschaft und sagte: Warum ist das Haus Gottes verlassen worden?* Und ich versammelte sie* und wies ihnen <wieder> ihren Platz an.", footnotes: ["℘ V. 17.25; Spr 28,4", "d. h. die Leviten und Sänger"] },
      { number: 12, text: "Und ganz Juda brachte den Zehnten vom Getreide und Most und Öl zu den Vorratskammern*.", footnotes: ["℘ Kap. 10,39; 4Mo 18,21; 2Chr 31,4"] },
      { number: 13, text: "Und ich bestimmte als Schatzmeister über die Vorräte* den Priester Schelemja und den Schreiber Zadok und Pedaja von den Leviten, und ihnen zur Seite Hanan, den Sohn Sakkurs, des Sohnes Mattanjas. Denn sie galten als zuverlässig*, und ihnen oblag es, ihren Brüdern auszuteilen.", footnotes: ["℘ Kap. 12,44", "℘ 2Kö 12,16; Mt 24,45"] },
      { number: 14, text: "Gedenke dafür meiner, mein Gott*, und lösche meine guten Taten* nicht aus, die ich am Haus meines Gottes und an dessen Aufgaben* erwiesen habe!*", footnotes: ["℘ V. 22.31; Kap. 5,19; 2Kö 20,3", "w. meine Treue o. Gnade", "o. an dessen Dienstordnungen", "℘ Ps 122,9; Hebr 6,10"] },
      { number: 15, text: "In jenen Tagen sah ich <einige> in Juda, die am Sabbat die Keltern traten und <Getreide>haufen einbrachten und auf Esel luden und auch Wein, Trauben und Feigen und allerlei Last und es am Sabbattag nach Jerusalem hereinbrachten*. Und ich warnte* <sie> an dem <selben> Tag, an dem sie die Lebensmittel verkauften.", footnotes: ["℘ Kap. 10,32; 2Mo 31,12-17; Am 8,5", "w. ich trat als Zeuge auf gegen"] },
      { number: 16, text: "Auch Tyrer wohnten darin; sie brachten Fisch und allerlei Ware herein und verkauften sie am Sabbat den Söhnen Juda, und <zwar> in Jerusalem." },
      { number: 17, text: "Da zog ich die Edlen* von Juda zur Rechenschaft* und sagte zu ihnen: Was ist das für eine schlimme Sache, die ihr da tut, dass ihr den Sabbattag entheiligt?*", footnotes: ["w. die Freigeborenen", "℘ V. 11; 3Mo 19,17; Mi 3,1.9", "℘ Hes 20,13.16.24"] },
      { number: 18, text: "Haben eure Väter nicht ebenso gehandelt, so dass unser Gott all dies Unheil über uns und über diese Stadt brachte?* Und ihr steigert die Zornglut über Israel, indem ihr den Sabbat entheiligt!*", footnotes: ["℘ 4Mo 32,14; Esr 9,14.15", "℘ Kap. 10,32; 2Mo 31,12-17; Am 8,5"] },
      { number: 19, text: "Und es geschah, sobald die Tore Jerusalems vor dem Sabbat dunkel wurden, befahl ich, dass die Torflügel geschlossen würden. Und ich befahl <weiter>, dass man sie bis nach dem Sabbat nicht öffnen solle. Und <einige> von meinen Dienern stellte ich an den Toren auf, <damit> keine Last am Sabbattag hereinkäme*.", footnotes: ["℘ Jer 17,21"] },
      { number: 20, text: "Da übernachteten die Händler und die Verkäufer von allerlei Ware draußen vor Jerusalem, einmal und zweimal." },
      { number: 21, text: "Und ich warnte* sie und sagte zu ihnen: Warum übernachtet ihr gegenüber der Mauer? Wenn ihr das noch einmal tut, werde ich Hand an euch legen! Von dieser Zeit an kamen sie nicht mehr am Sabbat*.", footnotes: ["w. ich trat als Zeuge auf gegen", "℘ Kap. 10,32"] },
      { number: 22, text: "Und ich befahl den Leviten, dass sie sich reinigen und als Wächter an die Tore kommen sollten*, damit man den Sabbattag heilig halten könne. Auch das gedenke mir, mein Gott*, und blicke mitleidig auf mich* nach der Größe deiner Güte*!", footnotes: ["℘ Kap. 12,30", "℘ V. 14.31", "w. <dein Auge> fließe <vor Tränen> über mich", "o. deiner Gnade\n℘ Ps 25,6.7"] },
      { number: 23, text: "Auch sah ich in jenen Tagen die Juden, die aschdodische, ammonitische <und> moabitische Frauen geheiratet hatten*.", footnotes: ["℘ Kap. 10,31; Rt 1,4"] },
      { number: 24, text: "Und die Hälfte ihrer Kinder redete aschdodisch, keines von ihnen konnte jüdisch reden, sondern <nur> in der Sprache des einen oder des anderen Volkes." },
      { number: 25, text: "Da ging ich mit ihnen ins Gericht* und verfluchte sie und schlug einige Männer von ihnen und raufte ihnen <die Haare> aus. Und ich beschwor sie bei Gott: Wenn ihr eure Töchter ihren Söhnen gebt und wenn ihr von ihren Töchtern für eure Söhne und für euch <Frauen> nehmt*!*", footnotes: ["w. Da hatte ich mit ihnen einen Rechtsstreit\n℘ V. 11.17; Kap. 5,6", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 5Mo 7,3.4"] },
      { number: 26, text: "Hat sich ihretwegen nicht <schon> Salomo, der König von Israel, versündigt?* Und einen König wie ihn hat es unter den vielen Nationen nicht gegeben*. Und er war geliebt von seinem Gott*, und <so> hatte Gott ihn zum König über ganz Israel gesetzt*; doch auch ihn haben die ausländischen Frauen zur Sünde verleitet.", footnotes: ["℘ 1Kö 11,1.6-8; 21,25; Spr 31,3", "℘ 1Kö 3,12.13", "℘ 2Sam 12,24", "℘ 1Kö 4,1"] },
      { number: 27, text: "Muss man <nun> auch von euch hören, dass ihr ganz das gleiche große Unrecht begeht, treulos gegen unseren Gott zu handeln dadurch, dass ihr ausländische Frauen heiratet!*", footnotes: ["℘ Kap. 10,31; Esr 9,14"] },
      { number: 28, text: "Und einer von den Söhnen Jojadas, des Sohnes Eljaschibs*, des Hohenpriesters, war der Schwiegersohn des Horoniters Sanballat*; den jagte ich von mir weg*.", footnotes: ["℘ Kap. 12,10.22", "℘ V. 4", "℘ Esr 10,8"] },
      { number: 29, text: "Gedenke es ihnen, mein Gott*, wegen der Verunreinigungen des Priesteramtes und des Bundes der Priester* und der Leviten*!", footnotes: ["℘ Kap. 6,14; Ps 59,6", "so mit einer hebr. Handschr., mehreren LXX-Handschr. und der syr. Üs.; Mas. T.: des Bundes des Priesteramtes", "℘ 3Mo 21,15; Mal 2,8"] },
      { number: 30, text: "So reinigte ich sie von allem Ausländischen, und ich stellte die Dienstordnungen für die Priester und Leviten auf, für jeden in seinem Arbeitsbereich*", footnotes: ["℘ 2Chr 13,10"] },
      { number: 31, text: "und für die Lieferung des Brennholzes* zu bestimmten Zeiten und für die <Abgabe der> Erstlinge*. Gedenke meiner, mein Gott*, zum Guten*!", footnotes: ["℘ Kap. 10,35", "℘ Kap. 10,38.39", "℘ V. 14.22", "℘ Kap. 5,19"] },
    ]},
  ]
};
